window.CURSOS_MARA = window.CURSOS_MARA || [];
window.CURSOS_MARA.push({"id":"c-ia","nombre":"IA aplicada al trabajo (general)","color":"#14B8A6","nivel":"Cursos libres de capacitación","familia":"Inteligencia Artificial aplicada","periodoTipo":null,"periodoNum":null,"desc":"Usa inteligencia artificial para redactar, resumir, ordenar datos, organizar tu semana y decidir mejor, sin tecnicismos y cuidando tu información. Con plantillas listas para copiar.","horas":10,"precio":990,"publicado":true,"proximamente":false,"modulos":[{"id":"c-ia-m1","titulo":"Módulo 1 — Entender la IA sin tecnicismos","resumen":"Antes de usar una herramienta hay que saber qué es y qué no es. En este módulo entiendes cómo «piensa» una IA, eliges la herramienta que te conviene, tienes tu primera conversación y aprendes las dos reglas que te protegen: verificar y cuidar tus datos. Cinco lecciones y una evaluación.","lecciones":[{"id":"c-ia-m1-l1","titulo":"Lección 1 — Qué es (y qué no es) la inteligencia artificial","objetivo":"explicar con tus palabras qué hace una IA de texto y por qué a veces se equivoca con total seguridad.","bloques":[{"tipo":"texto","texto":"Seguramente ya escuchaste que la inteligencia artificial «va a cambiar todo». Puede ser. Pero para usarla bien en tu trabajo no necesitas saber programar ni entender matemáticas. Necesitas entender <b>una sola idea</b>, y en esta lección la vas a tener clara."},{"tipo":"titulo","texto":"La idea en una frase"},{"tipo":"texto","texto":"Una inteligencia artificial de texto como ChatGPT, Gemini, Copilot o Claude <b>no busca la respuesta en una base de datos</b>. Lo que hace es <b>predecir, palabra por palabra, qué es lo más probable que siga</b> en un texto, a partir de millones de ejemplos que «leyó» durante su entrenamiento."},{"tipo":"destacado","texto":"<b>Piénsalo como el autocompletar de tu celular, pero gigante.</b> Cuando escribes «nos vemos» en WhatsApp, el teclado te sugiere «mañana». No sabe cuándo te vas a ver con esa persona: solo sabe que esa palabra suele seguir. La IA hace lo mismo, pero con párrafos enteros y muchísimo más contexto. Por eso escribe tan bien… y por eso a veces inventa."},{"tipo":"titulo","texto":"La consecuencia más importante: puede inventar"},{"tipo":"texto","texto":"Como su trabajo es producir texto que <i>suene</i> correcto, cuando no sabe algo no se queda callada: escribe algo plausible. A eso se le llama <b>alucinación</b>. Te puede dar un artículo de ley que no existe, una cifra inventada, una cita de un libro que nadie escribió o un teléfono equivocado, todo con la misma seguridad con la que te da información correcta."},{"tipo":"comparar","titulo":"Para qué es buena y para qué no","malTitulo":"No confíes a ciegas para…","mal":"• Cifras, fechas y datos exactos<br>• Leyes, impuestos, trámites vigentes<br>• Diagnósticos médicos o legales<br>• Noticias de hoy<br>• Cuentas matemáticas largas","bienTitulo":"Es excelente para…","bien":"• Redactar borradores (correos, avisos, publicaciones)<br>• Resumir textos largos<br>• Ordenar información desordenada<br>• Cambiar el tono de un mensaje<br>• Explicarte algo con ejemplos a tu medida<br>• Darte ideas y opciones","nota":"Regla práctica: la IA es una <b>asistente muy rápida que escribe bien</b>, no una fuente de verdad. Tú sigues siendo responsable de lo que envías."},{"tipo":"practica","rotulo":"¿Buena tarea para la IA?","instruccion":"Decide si le encargarías esto a la IA tal cual, o si tendrías que verificar.","preguntas":[{"p":"Redactar un aviso para tus clientes sobre el cambio de horario.","ops":["Sí, buena tarea","Solo con verificación extrema"],"correcta":0,"explica":"Es redacción: la IA brilla aquí. Tú solo revisas que los datos (horario, fechas) sean correctos."},{"p":"Decirte cuál es la tasa de ISR vigente para tu régimen.","ops":["Sí, buena tarea","No: verifícalo en fuente oficial"],"correcta":1,"explica":"Datos fiscales cambian y la IA puede estar desactualizada o inventar. Verifica en el SAT o con tu contador."},{"p":"Resumir un contrato de 20 páginas en puntos clave.","ops":["Sí, buena tarea","No sirve para nada"],"correcta":0,"explica":"Resumir es de sus fortalezas. Pero si vas a firmar algo, lee las cláusulas importantes tú mismo."},{"p":"Darte el teléfono de un proveedor en tu ciudad.","ops":["Sí, confiable","No: puede inventarlo"],"correcta":1,"explica":"Datos de contacto son el clásico ejemplo de alucinación."}]},{"tipo":"titulo","texto":"Tres mitos que conviene quitarse"},{"tipo":"lista","items":["<b>«La IA piensa como una persona.»</b> No. No tiene intenciones ni entiende como tú. Imita muy bien cómo escribimos.","<b>«La IA sabe todo lo de internet en tiempo real.»</b> Depende. Algunas herramientas pueden buscar en internet, pero su conocimiento base tiene una fecha de corte. Si le preguntas algo reciente, pídele que busque o verifica tú.","<b>«Si lo dice la IA, es correcto.»</b> Es el mito más peligroso. Suena segura siempre, tenga o no razón."]},{"tipo":"relacionar","rotulo":"Relaciona cada concepto","pares":[["Alucinación","Cuando la IA inventa algo con seguridad"],["Prompt","La instrucción que le escribes"],["Modelo de lenguaje","El «motor» que predice texto"],["Fecha de corte","Hasta cuándo llega lo que aprendió"]]},{"tipo":"reflexion","rotulo":"Piensa en tu trabajo","pregunta":"Escribe tres tareas de tu trabajo diario que implican escribir, resumir u ordenar información. Esas son tus primeras candidatas para usar IA.","ayuda":"Ej.: contestar correos de clientes, hacer la minuta de la junta, ordenar la lista de pedidos…"},{"tipo":"clave","items":["Una IA de texto <b>predice palabras</b>; no consulta una base de verdades.","Puede <b>alucinar</b>: inventar con total seguridad.","Úsala para redactar, resumir, ordenar y explicar. Verifica datos, cifras y leyes.","Tú eres responsable de lo que envías."]}]},{"id":"c-ia-m1-l2","titulo":"Lección 2 — Las herramientas: cuál usar y cómo empezar","objetivo":"conocer las principales herramientas de IA, elegir una para empezar y abrir tu cuenta.","bloques":[{"tipo":"texto","texto":"Hay decenas de herramientas de IA y todos los meses sale una nueva. No necesitas conocerlas todas. Con <b>una buena herramienta de conversación</b> puedes hacer el 90% de lo que verás en este curso. Todo lo que aprendas aquí funciona en cualquiera de ellas."},{"tipo":"tabla","titulo":"Las herramientas más usadas","encabezados":["Herramienta","De quién es","Dónde brilla"],"filas":[["<b>ChatGPT</b>","OpenAI","La más conocida. Muy completa, con versión gratuita y app para celular."],["<b>Gemini</b>","Google","Se integra con Gmail, Docs y Drive si usas cuenta de Google."],["<b>Copilot</b>","Microsoft","Integrada en Windows, Edge y Office (Word, Excel, Outlook) según tu licencia."],["<b>Claude</b>","Anthropic","Muy buena para textos largos, redacción cuidada y análisis de documentos."],["<b>Meta AI</b>","Meta","Viene dentro de WhatsApp, Instagram y Facebook. Cómoda para cosas rápidas."]],"nota":"Las versiones gratuitas alcanzan para todo este curso. Las de pago agregan más capacidad y funciones; decide después de usarlas un tiempo. Los nombres y funciones cambian seguido: lo importante es la forma de trabajar, que es la misma en todas."},{"tipo":"destacado","texto":"<b>Recomendación para empezar:</b> si en tu trabajo usan Microsoft Office, prueba Copilot. Si usas Gmail y Google Drive, prueba Gemini. Si no tienes preferencia, ChatGPT o Claude son excelentes puntos de partida. Elige <b>una</b> y quédate con ella todo el curso."},{"tipo":"titulo","texto":"Cómo abrir tu cuenta (5 minutos)"},{"tipo":"pasos","rotulo":"Palomea cada paso conforme lo hagas","pasos":["Entra desde tu navegador a la página oficial de la herramienta que elegiste (escribe su nombre en el buscador y verifica que sea el sitio oficial) o descarga la app oficial desde la tienda de tu celular.","Toca «Registrarse» o «Sign up». Puedes usar tu cuenta de Google, Microsoft o Apple, o tu correo.","Si te pide verificar tu correo o tu teléfono, hazlo. Es normal.","Al entrar vas a ver una caja de texto grande abajo. Ahí se escribe. Eso es todo.","Busca en el menú la opción de configuración o «Settings» y revisa el apartado de privacidad o datos (lo vemos a fondo en la lección 5)."]},{"tipo":"destacado","texto":"<b>Cuidado con las imitaciones:</b> hay apps con nombres parecidos que cobran suscripciones caras o piden datos de más. Descarga solo la app del desarrollador oficial (OpenAI, Google, Microsoft, Anthropic, Meta)."},{"tipo":"titulo","texto":"Las partes de la pantalla"},{"tipo":"lista","items":["<b>La caja de texto:</b> donde escribes tu instrucción. Enter envía; para cambiar de renglón sin enviar usa Shift + Enter.","<b>El clip o el signo +:</b> para adjuntar archivos o fotos (PDF, Word, Excel, imágenes).","<b>El micrófono:</b> para dictar en lugar de escribir. Muy útil en el celular.","<b>El historial</b> (a la izquierda o en el menú): tus conversaciones anteriores. Puedes retomarlas.","<b>«Nueva conversación» o «New chat»:</b> empieza de cero. Úsala cuando cambies de tema."]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Trabajas todo el día en Excel y Outlook de Microsoft. ¿Qué herramienta te conviene probar primero?","ops":["Copilot","Meta AI","Ninguna"],"correcta":0,"explica":"Copilot se integra con Office."},{"p":"Quieres escribir un mensaje de varios renglones sin enviarlo a medias. ¿Qué haces?","ops":["Presiono Enter en cada renglón","Uso Shift + Enter para bajar de renglón","Escribo todo en una línea"],"correcta":1},{"p":"Terminaste un tema y quieres preguntar algo totalmente distinto.","ops":["Sigo en la misma conversación","Abro una nueva conversación"],"correcta":1,"explica":"Así el contexto anterior no se mezcla."}]},{"tipo":"reflexion","rotulo":"Tu elección","pregunta":"¿Qué herramienta elegiste y por qué? Si ya abriste tu cuenta, escribe aquí la primera pregunta que le hiciste.","ayuda":"Elegí… porque…"},{"tipo":"clave","items":["Con <b>una</b> herramienta de conversación haces casi todo.","Elige según tu ecosistema: Office → Copilot, Google → Gemini, o ChatGPT/Claude.","Descarga solo apps oficiales.","Nueva conversación para cada tema nuevo."]}]},{"id":"c-ia-m1-l3","titulo":"Lección 3 — Tu primera conversación","objetivo":"tener una conversación útil de ida y vuelta con la IA y corregir su respuesta hasta que sirva.","bloques":[{"tipo":"texto","texto":"El error más común de quien empieza es tratar a la IA como un buscador: escribir tres palabras, leer la respuesta y cerrar. La IA funciona mucho mejor como <b>una conversación</b>: le pides algo, ves qué te dio y le pides ajustes. La segunda o tercera respuesta casi siempre es mucho mejor que la primera."},{"tipo":"comparar","titulo":"Buscador vs. conversación","malTitulo":"Como buscador","mal":"<i>«junta equipo motivar»</i><br><br>Respuesta genérica de 10 consejos que ya conocías.","bienTitulo":"Como conversación","bien":"<i>«Mañana tengo junta con mi equipo de 6 vendedores. Este mes no llegamos a la meta y están desanimados. Dame 3 ideas para abrir la junta en 5 minutos sin regañar.»</i><br><br>Luego: <i>«Me gusta la segunda. Escríbeme lo que diría, en tono cercano.»</i>"},{"tipo":"titulo","texto":"Ejercicio guiado: tu primera conversación real"},{"tipo":"texto","texto":"Abre tu herramienta en otra pestaña o en tu celular y sigue estos pasos. Copia cada instrucción con el botón y pégala."},{"tipo":"plantilla","rotulo":"Paso 1 — Pide algo concreto","texto":"Soy [tu puesto] en [tipo de empresa]. Necesito escribir un mensaje para avisar a mis compañeros que la junta del lunes se cambia al martes a las 10 am. Escríbelo breve y amable."},{"tipo":"plantilla","rotulo":"Paso 2 — Ajusta el resultado","texto":"Hazlo más corto, para mandarlo por WhatsApp, y agrega que por favor confirmen con un 👍."},{"tipo":"plantilla","rotulo":"Paso 3 — Pide opciones","texto":"Dame dos versiones más: una más formal para correo y una muy informal."},{"tipo":"destacado","texto":"<b>Fíjate en lo que acaba de pasar:</b> no tuviste que volver a explicar la situación en el paso 2 ni en el 3. La IA <b>recuerda lo que llevan platicado dentro de la misma conversación</b>. Por eso conviene seguir en el mismo chat mientras trabajas un tema, y abrir uno nuevo cuando cambias de tema."},{"tipo":"titulo","texto":"Frases para corregir el rumbo"},{"tipo":"tabla","titulo":"Cuando la respuesta no te convence","encabezados":["Si pasa esto…","Escríbele…"],"filas":[["Es muy larga","«Resúmelo en máximo 5 renglones.»"],["Suena muy formal / robótico","«Hazlo más natural, como lo diría una persona de México.»"],["Es muy genérico","«Aterrízalo a mi caso: [agrega detalles].»"],["No entendiste algo","«Explícamelo como si tuviera 12 años, con un ejemplo.»"],["Quieres alternativas","«Dame 3 opciones diferentes.»"],["Algo está mal","«Esto no es correcto: [explica]. Corrígelo.»"]]},{"tipo":"practica","rotulo":"¿Qué le dirías?","preguntas":[{"p":"La IA te dio un correo perfecto pero de 300 palabras y lo necesitas de 80.","ops":["Empiezo una conversación nueva","Le pido: «Resúmelo en máximo 80 palabras»","Lo recorto yo a mano"],"correcta":1},{"p":"La respuesta suena a traducción, con palabras que no se usan en México.","ops":["«Hazlo más natural, en español de México»","La acepto así","Le escribo en inglés"],"correcta":0},{"p":"La IA puso mal la fecha de la junta.","ops":["Cierro y ya no la uso","Le digo: «La fecha correcta es el martes 14; corrígelo»"],"correcta":1}]},{"tipo":"titulo","texto":"Dictar en lugar de escribir"},{"tipo":"texto","texto":"Si escribir en el celular te cuesta, usa el <b>micrófono</b>. Habla como si le explicaras a un compañero: «Oye, necesito un mensaje para…». La IA entiende perfectamente aunque hables con muletillas. Es de las funciones que más tiempo ahorran."},{"tipo":"reflexion","rotulo":"Tu primera prueba","pregunta":"Haz tu propia conversación de 3 pasos con una tarea real de esta semana. Anota aquí qué pediste y qué tanto mejoró la respuesta del paso 1 al paso 3.","ayuda":"Pedí… La primera respuesta… Después de ajustarla…"},{"tipo":"clave","items":["Trátala como conversación, no como buscador.","La segunda o tercera respuesta suele ser la buena: pide ajustes.","Recuerda lo platicado en el mismo chat; nuevo tema = nuevo chat.","Puedes dictar con el micrófono."]}]},{"id":"c-ia-m1-l4","titulo":"Lección 4 — Verificar: la regla que te protege","objetivo":"detectar cuándo una respuesta necesita verificación y aplicar un método rápido para comprobarla.","bloques":[{"tipo":"texto","texto":"Ya sabes que la IA puede inventar. En esta lección aprendes <b>cuándo sospechar</b> y <b>cómo verificar en dos minutos</b>, para que puedas usarla con confianza sin meterte en problemas."},{"tipo":"destacado","texto":"<b>Caso real que se volvió famoso:</b> en 2023, en Estados Unidos, unos abogados presentaron ante un juez un escrito con casos judiciales que la IA había inventado. Los casos sonaban perfectos, con números y nombres. No existían. Los abogados fueron sancionados. La IA no mintió «a propósito»: hizo lo que hace, producir texto que suena bien."},{"tipo":"titulo","texto":"El semáforo de la verificación"},{"tipo":"tabla","titulo":"Qué tanto revisar","encabezados":["Nivel","Tipo de contenido","Qué hacer"],"filas":[["🟢 Verde","Redacción, tono, ideas, lluvia de opciones, resúmenes de un texto que tú le diste","Lee y ajusta. Riesgo bajo."],["🟡 Amarillo","Explicaciones generales, pasos de un proceso, recomendaciones","Revisa que tenga sentido; compara con otra fuente si vas a actuar."],["🔴 Rojo","Cifras, fechas, leyes, impuestos, salud, datos de contacto, citas textuales, cálculos","Verifica SIEMPRE en fuente oficial antes de usarlo."]]},{"tipo":"titulo","texto":"Método de verificación en 4 pasos"},{"tipo":"pasos","rotulo":"Cuando algo sea rojo","pasos":["Pregúntale a la IA: <i>«¿De dónde sale este dato? ¿Qué tan seguro estás?»</i> A veces ella misma reconoce que no está segura.","Pídele la fuente y <b>ábrela tú</b>. Si te da un enlace, entra y confirma que dice lo que ella dice. Si no te da fuente, trátalo como no verificado.","Busca el dato en la <b>fuente oficial</b>: SAT, IMSS, DOF, la página de la empresa, el documento original.","Si no lo pudiste confirmar, <b>no lo uses</b> o dilo claramente: «dato por confirmar»."]},{"tipo":"plantilla","rotulo":"Instrucción para que la IA sea más honesta","texto":"Responde solo con información de la que estés seguro. Si no sabes algo o no estás seguro, dilo claramente en lugar de adivinar. Señala qué partes de tu respuesta debería verificar en una fuente oficial.","nota":"Agrégala al final de tus preguntas importantes. No elimina los errores, pero los reduce y te avisa dónde revisar."},{"tipo":"practica","rotulo":"¿Verde, amarillo o rojo?","preguntas":[{"p":"La IA te sugiere 5 títulos para tu presentación.","ops":["Verde","Amarillo","Rojo"],"correcta":0},{"p":"Te dice que el aguinaldo mínimo por ley son 15 días de salario.","ops":["Verde","Amarillo","Rojo"],"correcta":2,"explica":"Es un dato legal. Aunque sea correcto hoy, verifica en la Ley Federal del Trabajo o fuente oficial antes de usarlo con clientes o empleados."},{"p":"Te explica en general cómo organizar un inventario.","ops":["Verde","Amarillo","Rojo"],"correcta":1},{"p":"Te calcula el total de una lista de 40 facturas.","ops":["Verde","Amarillo","Rojo"],"correcta":2,"explica":"Las IA de texto pueden equivocarse en cálculos largos. Usa Excel para sumar (lo vemos en el módulo 4)."},{"p":"Resume un PDF que tú le subiste.","ops":["Verde","Amarillo","Rojo"],"correcta":0,"explica":"Riesgo bajo, pero si el resumen incluye cifras importantes, confírmalas en el PDF."}]},{"tipo":"reflexion","rotulo":"Tu zona roja","pregunta":"¿Qué tipo de información de tu trabajo es «roja» (no puede ir mal)? Escribe dos ejemplos y dónde la verificarías.","ayuda":"Ej.: precios de la lista vigente → sistema de la empresa…"},{"tipo":"clave","items":["Verde: redacción e ideas. Amarillo: explicaciones. Rojo: datos, leyes, cifras, salud.","Pide la fuente y ábrela tú.","Si no puedes confirmarlo, no lo uses."]}]},{"id":"c-ia-m1-l5","titulo":"Lección 5 — Privacidad: lo que nunca debes pegar","objetivo":"saber qué información no compartir con una IA y cómo usarla sin exponer datos tuyos, de clientes o de tu empresa.","bloques":[{"tipo":"texto","texto":"Lo que escribes en una herramienta de IA viaja a los servidores de una empresa. Según la herramienta y su configuración, puede guardarse y, en algunos casos, usarse para mejorar el sistema. No significa que no debas usarla: significa que hay <b>información que nunca debe entrar ahí</b>."},{"tipo":"comparar","titulo":"La regla del «¿lo publicaría?»","malTitulo":"Nunca pegues","mal":"• Contraseñas, NIP, códigos de verificación<br>• Números de tarjeta o cuentas<br>• CURP, RFC, INE de personas<br>• Datos de salud de alguien<br>• Datos personales de clientes (nombre + teléfono + dirección)<br>• Información confidencial de tu empresa: estrategias, contratos, cifras no públicas","bienTitulo":"Mejor así","bien":"• Cambia nombres por «Cliente A», «Proveedor B»<br>• Quita teléfonos, correos y direcciones<br>• Redondea cifras o usa ejemplos ficticios<br>• Describe la situación en general<br>• Usa la herramienta que tu empresa autorizó","nota":"Si no lo publicarías en un grupo de WhatsApp con desconocidos, no lo pegues en una IA pública."},{"tipo":"titulo","texto":"Anonimizar: el truco que resuelve casi todo"},{"tipo":"texto","texto":"Casi siempre puedes obtener la misma ayuda sin datos reales. La IA no necesita saber que la clienta se llama María González y vive en la calle Hidalgo 45 para ayudarte a contestarle un reclamo. Necesita saber <b>qué pasó</b>."},{"tipo":"comparar","titulo":"Mismo resultado, sin riesgo","malTitulo":"Con datos reales","mal":"«Contesta a María González López, cliente 458921, tel. 477 123 4567, que reclama que le cobramos dos veces $3,450 en su tarjeta terminación 8812.»","bienTitulo":"Anonimizado","bien":"«Contesta a una clienta que reclama que le cobramos dos veces una compra. Ya verificamos que fue error nuestro y el reembolso tarda 5 días hábiles. Tono empático y profesional.»"},{"tipo":"titulo","texto":"Revisa tu configuración"},{"tipo":"pasos","rotulo":"Haz esto una vez","pasos":["Entra a Configuración o «Settings» de tu herramienta.","Busca la sección de «Privacidad», «Datos» o «Data controls».","Revisa si existe una opción para que tus conversaciones no se usen para entrenar o mejorar los modelos, y decide si la activas.","Averigua si en tu trabajo hay una herramienta de IA autorizada o una política de uso. Pregunta a sistemas o a tu jefe.","Si vas a usar la IA con información de trabajo, prefiere la versión empresarial que tu empresa contrate: suelen tener más protecciones de datos."]},{"tipo":"destacado","texto":"<b>En México</b> la protección de datos personales está regulada por ley. Si trabajas con datos de clientes, compartirlos sin cuidado con un servicio externo puede ser un problema legal para ti y tu empresa, no solo un descuido. Ante la duda, anonimiza."},{"tipo":"practica","rotulo":"¿Lo pegarías?","preguntas":[{"p":"Un correo de un cliente con su nombre, dirección y número de pedido, para que la IA te ayude a contestarlo.","ops":["Sí, tal cual","Sí, pero quitando nombre, dirección y número"],"correcta":1},{"p":"La contraseña de tu correo para que la IA «revise tu bandeja».","ops":["Sí","Nunca"],"correcta":1,"explica":"Ninguna herramienta legítima necesita tu contraseña en el chat."},{"p":"Un texto público de la página de tu empresa para mejorarlo.","ops":["Sí, es público","No"],"correcta":0},{"p":"El Excel con los sueldos de todo tu equipo para sacar el promedio.","ops":["Sí","No, o solo en una herramienta autorizada por la empresa y sin nombres"],"correcta":1}]},{"tipo":"completar","rotulo":"Anonimiza la frase","instruccion":"Escribe cómo nombrarías a la persona en lugar de su nombre real. Cualquier etiqueta genérica sirve.","items":[{"frase":"«Juan Pérez, de Aceros del Bajío, no ha pagado.» → «El ___ no ha pagado.»","resp":["cliente","cliente A","proveedor","cliente X"],"pista":"Por ejemplo: cliente, o cliente A."}]},{"tipo":"reflexion","rotulo":"Tu política personal","pregunta":"Escribe tus 3 reglas personales de privacidad al usar IA en el trabajo.","ayuda":"1. Nunca… 2. Siempre cambio… 3. Antes de usarla con datos del trabajo…"},{"tipo":"clave","items":["Nunca: contraseñas, tarjetas, identificaciones, salud, datos de clientes, secretos de la empresa.","Anonimiza: la IA necesita saber qué pasó, no quién es.","Revisa la configuración de privacidad y la política de tu empresa."]}]}],"quiz":{"titulo":"Evaluación del módulo 1","preguntas":[{"p":"Una IA de texto principalmente…","ops":["Busca la respuesta en internet","Predice qué palabra sigue","Consulta una enciclopedia","Copia de una base de datos"],"correcta":1},{"p":"Que la IA «alucine» significa que…","ops":["Se traba","Inventa información con seguridad","Se tarda mucho","Responde en otro idioma"],"correcta":1},{"p":"¿Cuál NO es una buena tarea para delegar sin verificar?","ops":["Resumir un texto que le diste","Redactar un borrador","Darte una cifra oficial","Cambiar el tono de un mensaje"],"correcta":2},{"p":"Si usas Outlook y Excel todo el día, la herramienta más integrada es…","ops":["Gemini","Copilot","Meta AI","Ninguna"],"correcta":1},{"p":"Para bajar de renglón sin enviar el mensaje usas…","ops":["Enter","Shift + Enter","Ctrl + Z","Esc"],"correcta":1},{"p":"La primera respuesta no te convenció. Lo mejor es…","ops":["Cerrar y buscar en Google","Pedir ajustes en la misma conversación","Copiarla tal cual","Empezar otra herramienta"],"correcta":1},{"p":"Un dato «rojo» que siempre debes verificar es…","ops":["Ideas para un título","El tono de un correo","Un porcentaje de impuestos","Un resumen de tu propio texto"],"correcta":2},{"p":"Si la IA te da un dato y no puedes confirmarlo en una fuente oficial…","ops":["Lo usas igual","No lo usas o lo marcas como por confirmar","Le preguntas otra vez hasta que diga lo mismo","Lo publicas"],"correcta":1},{"p":"¿Qué información NUNCA debes pegar en una IA pública?","ops":["Un texto de tu página web","Una idea para un evento","Los datos de tarjeta de un cliente","Un borrador de aviso"],"correcta":2},{"p":"Anonimizar significa…","ops":["Borrar la conversación","Cambiar datos personales por etiquetas genéricas","Usar la IA sin cuenta","Escribir en inglés"],"correcta":1}]}},{"id":"c-ia-m2","titulo":"Módulo 2 — Pedir bien: el arte de la instrucción","resumen":"La diferencia entre un resultado inservible y uno que puedes usar tal cual está en cómo lo pides. En este módulo aprendes la fórmula de las cuatro partes, a dar contexto y ejemplos, a controlar el formato, a pulir en varias vueltas y a armar tu propia biblioteca de instrucciones. Cinco lecciones y una evaluación.","lecciones":[{"id":"c-ia-m2-l1","titulo":"Lección 1 — La fórmula de las cuatro partes","objetivo":"escribir instrucciones completas con papel, tarea, contexto y formato.","bloques":[{"tipo":"texto","texto":"A la instrucción que le escribes a la IA se le llama <b>prompt</b> (se pronuncia «prompt»). Una instrucción vaga da un resultado vago. La buena noticia es que no hay que ser experto: casi toda instrucción buena tiene las mismas cuatro partes."},{"tipo":"tabla","titulo":"Las cuatro partes","encabezados":["Parte","Qué le dices","Ejemplo"],"filas":[["<b>1. Papel</b>","Quién quieres que sea","«Eres el encargado de atención a clientes de una escuela en línea.»"],["<b>2. Tarea</b>","Qué quieres exactamente","«Redacta la respuesta a este correo de una mamá molesta.»"],["<b>3. Contexto</b>","Lo que necesita saber","«Pagó y no le llegó el acceso. Ya lo activamos. Podemos darle una semana extra.»"],["<b>4. Formato</b>","Cómo lo quieres","«Máximo 120 palabras, tono amable, sin tecnicismos, cierra con una pregunta.»"]]},{"tipo":"comparar","titulo":"La misma tarea, dos instrucciones","malTitulo":"Vaga","mal":"«Contesta este correo.»<br><br>Resultado: una respuesta genérica, muy formal, que promete cosas que no puedes cumplir.","bienTitulo":"Con las 4 partes","bien":"«Eres el encargado de atención a clientes de una escuela en línea. Redacta la respuesta a este correo de una mamá molesta. Contexto: pagó y no le llegó el acceso; ya lo activamos y le damos una semana extra de regalo. Máximo 120 palabras, tono amable, sin tecnicismos, cierra preguntando si ya pudo entrar.»"},{"tipo":"destacado","texto":"<b>¿Por qué funciona el «papel»?</b> Porque la IA ajusta vocabulario, tono y nivel de detalle a ese rol. «Eres un contador» produce algo muy distinto de «eres un maestro de primaria», aunque la tarea sea la misma."},{"tipo":"relacionar","rotulo":"¿Qué parte es cada frase?","pares":[["«Eres un asesor de ventas con experiencia»","Papel"],["«Escribe tres mensajes para recuperar clientes»","Tarea"],["«Vendemos seguros de auto y el cliente no renovó»","Contexto"],["«En viñetas, máximo 50 palabras cada uno»","Formato"]]},{"tipo":"plantilla","rotulo":"Plantilla base — cópiala y llénala","texto":"Eres [papel: quién quieres que sea].\nTu tarea es [qué quieres exactamente].\nContexto: [situación, datos importantes, a quién va dirigido, qué quieres lograr].\nFormato: [largo, tono, estructura: viñetas, tabla, párrafos].","nota":"No tiene que estar en ese orden ni usar esas palabras. Lo importante es que las cuatro cosas estén."},{"tipo":"practica","rotulo":"¿Qué le falta?","preguntas":[{"p":"«Eres un experto en marketing. Escribe un anuncio.»","ops":["Papel","Contexto y formato","Tarea"],"correcta":1,"explica":"¿Anuncio de qué, para quién, dónde se publica, de qué largo?"},{"p":"«Escribe un post para Facebook de 80 palabras, tono alegre, sobre nuestra promoción de 2x1 en pizzas este viernes.»","ops":["Papel (aunque así ya funciona bien)","Tarea","Formato"],"correcta":0,"explica":"El papel es la parte más opcional: con buen contexto y formato ya da buen resultado."},{"p":"«Eres mi asistente. Ayúdame con lo de la junta.»","ops":["Casi todo: tarea clara, contexto y formato","Solo el formato","Nada"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Escribe tu primera instrucción de 4 partes","pregunta":"Toma una tarea real de tu trabajo y escribe aquí la instrucción completa con papel, tarea, contexto y formato. Luego pruébala en tu herramienta.","ayuda":"Eres… Tu tarea es… Contexto: … Formato: …"},{"tipo":"clave","items":["<b>Papel · Tarea · Contexto · Formato</b>.","El contexto es la parte que más mejora el resultado.","Guarda tu plantilla base."]}]},{"id":"c-ia-m2-l2","titulo":"Lección 2 — Contexto y ejemplos: dale lo que tú sabes","objetivo":"dar el contexto correcto y usar ejemplos para que la IA imite exactamente el estilo que buscas.","bloques":[{"tipo":"texto","texto":"La IA no sabe nada de tu empresa, tus clientes, tu jefe ni lo que pasó ayer. Todo lo que no le digas, lo va a suponer, y sus suposiciones son genéricas. <b>El contexto es tu ventaja</b>: lo que tú sabes y ella no."},{"tipo":"titulo","texto":"Las 5 preguntas del buen contexto"},{"tipo":"lista","items":["<b>¿Para quién es?</b> — cliente, jefe, compañero, público general. Su edad, su nivel, su relación contigo.","<b>¿Qué pasó?</b> — la situación concreta, en dos o tres frases.","<b>¿Qué quieres lograr?</b> — que pague, que se calme, que acepte, que entienda.","<b>¿Qué NO quieres?</b> — «no ofrezcas descuentos», «no menciones al proveedor».","<b>¿Qué datos debe usar?</b> — fechas, precios, nombres de productos (anonimizados si son personales)."]},{"tipo":"destacado","texto":"<b>Pega el material.</b> Si vas a contestar un correo, pega el correo (sin datos sensibles). Si vas a mejorar un texto, pega el texto. Si vas a resumir un documento, adjúntalo. La IA trabaja muchísimo mejor sobre material real que sobre tu descripción del material."},{"tipo":"titulo","texto":"El truco de los ejemplos"},{"tipo":"texto","texto":"Si quieres que algo salga <b>con un estilo específico</b> (el de tu marca, el de tus correos, el de tus publicaciones), no lo describas: <b>muéstraselo</b>. Pega uno o dos ejemplos y pídele que siga ese estilo. Es la técnica más poderosa para que suene a ti."},{"tipo":"plantilla","rotulo":"Plantilla — imitar un estilo","texto":"Te voy a mostrar dos publicaciones que hicimos antes y que funcionaron muy bien. Quiero que escribas una nueva con el mismo estilo, largo y tono, pero sobre [nuevo tema].\n\nEjemplo 1:\n[pega aquí]\n\nEjemplo 2:\n[pega aquí]"},{"tipo":"comparar","titulo":"Describir vs. mostrar","malTitulo":"Describiendo","mal":"«Escribe un post cercano, divertido pero profesional, con algunos emojis, como lo haría nuestra marca.»<br>La IA adivina qué significa «como nuestra marca».","bienTitulo":"Mostrando","bien":"«Así escribimos: [ejemplo real]. Escribe uno igual sobre la nueva sucursal.»<br>La IA copia el ritmo, los emojis, el largo y el tipo de humor."},{"tipo":"practica","rotulo":"¿Qué contexto le falta?","preguntas":[{"p":"«Escribe un mensaje para cobrarle a un cliente.» ¿Qué dato es más importante agregar?","ops":["Qué tan atrasado está el pago y qué relación tienen","El color del logo","La hora del día"],"correcta":0},{"p":"Quieres que un texto suene exactamente como tus correos. Lo mejor es…","ops":["Decirle «que suene como yo»","Pegarle 2 correos tuyos como ejemplo","Pedirle que sea formal"],"correcta":1},{"p":"Quieres una respuesta a un correo difícil. ¿Qué haces con el correo original?","ops":["Lo describo de memoria","Lo pego, quitando datos personales"],"correcta":1}]},{"tipo":"plantilla","rotulo":"Plantilla — que te pregunte lo que falta","texto":"Quiero que me ayudes a [tarea]. Antes de responder, hazme las preguntas que necesites para hacerlo bien. Pregúntame una por una.","nota":"Úsala cuando no sepas qué contexto darle. La IA te entrevista y luego escribe con toda la información."},{"tipo":"reflexion","rotulo":"Tu contexto de siempre","pregunta":"Escribe un párrafo de contexto sobre tu trabajo que puedas reutilizar: a qué te dedicas, qué empresa o giro, quiénes son tus clientes, qué tono usan. Lo vas a pegar al inicio de muchas conversaciones.","ayuda":"Trabajo en… Nuestros clientes son… Usamos un tono…"},{"tipo":"clave","items":["Todo lo que no digas, la IA lo supone.","Pega el material real (sin datos sensibles).","Para un estilo: muéstrale ejemplos.","Si no sabes qué decir, pídele que te pregunte."]}]},{"id":"c-ia-m2-l3","titulo":"Lección 3 — Controla el formato: tablas, listas, largo y tono","objetivo":"pedir exactamente la forma de la respuesta para poder usarla sin reescribirla.","bloques":[{"tipo":"texto","texto":"Una respuesta puede tener buen contenido y aun así no servirte porque viene en la forma equivocada: un párrafo enorme cuando necesitabas una lista, o un texto formal cuando era para WhatsApp. El formato se pide, y la IA lo respeta muy bien."},{"tipo":"tabla","titulo":"Qué puedes pedir","encabezados":["Quieres…","Pídelo así"],"filas":[["Largo exacto","«máximo 80 palabras», «en 3 renglones», «una sola frase»"],["Lista","«en viñetas», «numerado del más al menos importante»"],["Tabla","«en una tabla con columnas: tarea, responsable, fecha»"],["Tono","«formal», «cercano», «como a un amigo», «firme pero amable»"],["Nivel","«para alguien que no sabe nada del tema», «para el director»"],["Estructura","«empieza con la conclusión», «termina con una pregunta»"],["Para copiar a Excel","«en una tabla que pueda pegar en Excel»"]]},{"tipo":"destacado","texto":"<b>Tip para tablas:</b> cuando la IA te da una tabla, puedes seleccionarla, copiarla y pegarla directo en Excel o Google Sheets; casi siempre respeta las columnas. Así conviertes un texto desordenado en una hoja de cálculo en segundos."},{"tipo":"comparar","titulo":"Mismo contenido, otro formato","malTitulo":"Sin formato","mal":"«Dame ideas para mejorar la atención en mi tienda.»<br>→ 700 palabras en párrafos.","bienTitulo":"Con formato","bien":"«Dame 5 ideas para mejorar la atención en mi tienda de ropa, en una tabla con columnas: idea, costo aproximado (bajo/medio/alto), qué tan rápido se ve el resultado.»"},{"tipo":"practica","rotulo":"¿Qué formato pedirías?","preguntas":[{"p":"Necesitas repartir tareas de un evento entre 4 personas.","ops":["Un párrafo","Una tabla: tarea, responsable, fecha límite","Un poema"],"correcta":1},{"p":"Es un aviso que se va a leer en el celular.","ops":["Máximo 3 renglones, directo","Una carta formal de una cuartilla"],"correcta":0},{"p":"Tu jefe tiene 2 minutos para leer tu reporte.","ops":["Empieza con la conclusión y 3 viñetas","Cuenta todo en orden cronológico"],"correcta":0}]},{"tipo":"titulo","texto":"El tono en México"},{"tipo":"texto","texto":"Las IA a veces escriben en un español «neutro» que suena a traducción: «estimado usuario», «le informamos que», «¡Genial!». Si quieres que suene natural, díselo: <b>«en español de México, natural, como lo diría una persona»</b>. Y si tratas de usted o de tú, especifícalo."},{"tipo":"plantilla","rotulo":"Frase comodín de formato y tono","texto":"Escríbelo en español de México, natural y claro, tratando de [usted / tú]. Evita frases de plantilla como \"le informamos que\" o \"estimado cliente\". Máximo [número] palabras."},{"tipo":"ordenar","rotulo":"Arma la instrucción de formato","items":[{"frase":"Hazlo en una tabla con tres columnas","es":"Formato tabla"},{"frase":"Resúmelo en máximo cinco viñetas","es":"Formato lista"},{"frase":"Empieza con la conclusión","es":"Estructura"}]},{"tipo":"reflexion","rotulo":"Tus formatos frecuentes","pregunta":"¿En qué formato necesitas normalmente la información en tu trabajo? (correo, WhatsApp, tabla, presentación, reporte). Escribe la frase de formato que usarías para cada uno.","ayuda":"Para WhatsApp: … Para mi jefe: …"},{"tipo":"clave","items":["El formato se pide: largo, lista, tabla, tono, nivel, estructura.","Las tablas se pegan directo en Excel.","Pide «español de México, natural» para evitar el tono de traducción."]}]},{"id":"c-ia-m2-l4","titulo":"Lección 4 — Pulir en varias vueltas","objetivo":"mejorar un resultado paso a paso con instrucciones de ajuste y pedirle a la IA que se revise a sí misma.","bloques":[{"tipo":"texto","texto":"Los usuarios que sacan más provecho de la IA no escriben la instrucción perfecta a la primera: <b>trabajan en vueltas</b>. Piden un primer borrador, lo revisan, piden cambios específicos y en tres o cuatro vueltas tienen algo excelente. Así trabajarías con un asistente humano, y así funciona mejor."},{"tipo":"titulo","texto":"Las instrucciones de ajuste más útiles"},{"tipo":"tabla","titulo":"Tu caja de herramientas","encabezados":["Instrucción","Para qué"],"filas":[["«Mantén todo igual, pero cambia solo…»","Evitar que reescriba lo que ya estaba bien."],["«Dame 3 versiones distintas»","Elegir la mejor o combinar."],["«Combina el inicio de la 1 con el cierre de la 3»","Armar tu versión ideal."],["«¿Qué le falta a este texto?»","Que detecte huecos."],["«Revísalo como si fueras [el cliente / mi jefe] y dime qué no le convencería»","Anticipar objeciones."],["«Hazlo más corto sin perder [lo importante]»","Recortar con cuidado."]]},{"tipo":"destacado","texto":"<b>La más valiosa: «Mantén todo igual, pero…».</b> Si solo dices «cámbialo», la IA suele reescribir todo y se pierde lo que ya te gustaba. Sé quirúrgico."},{"tipo":"titulo","texto":"Que se revise sola"},{"tipo":"plantilla","rotulo":"Autocrítica","texto":"Revisa tu respuesta anterior como si fueras un editor exigente. Dime 3 debilidades concretas y luego escribe una versión mejorada que las corrija."},{"tipo":"plantilla","rotulo":"Ponerse en los zapatos del lector","texto":"Lee este texto como si fueras [el cliente que lo va a recibir]. ¿Qué parte te molestaría, confundiría o te haría no responder? Luego propón los cambios."},{"tipo":"titulo","texto":"Ejemplo de 4 vueltas"},{"tipo":"lista","items":["<b>Vuelta 1:</b> «Escribe un anuncio para vacante de recepcionista en un consultorio dental en León.» → Sale genérico.","<b>Vuelta 2:</b> «Agrega: horario de 9 a 6, sueldo competitivo, se requiere experiencia en agenda. Tono cercano.» → Mucho mejor.","<b>Vuelta 3:</b> «Mantén todo igual, pero hazlo de 80 palabras para Facebook y agrega 3 emojis.» → Casi listo.","<b>Vuelta 4:</b> «Dame 3 opciones de primera línea que llamen la atención.» → Eliges la mejor. Listo en 5 minutos."]},{"tipo":"practica","rotulo":"¿Qué instrucción de ajuste usarías?","preguntas":[{"p":"El correo te encanta, pero el saludo es muy formal.","ops":["«Vuelve a escribirlo»","«Mantén todo igual, pero cambia solo el saludo por uno más cercano»"],"correcta":1},{"p":"No sabes qué versión te gusta más.","ops":["«Dame 3 versiones distintas»","«Hazlo mejor»"],"correcta":0},{"p":"Vas a mandar una propuesta a un cliente difícil.","ops":["La mando tal cual","«Léela como si fueras el cliente y dime qué objeciones tendría»"],"correcta":1}]},{"tipo":"reflexion","rotulo":"Practica en 4 vueltas","pregunta":"Toma un texto que tengas que escribir esta semana y trabájalo en 4 vueltas con tu herramienta. Anota aquí qué cambió en cada vuelta.","ayuda":"V1: … V2: … V3: … V4: …"},{"tipo":"clave","items":["Trabaja en vueltas: borrador → ajustes → versión final.","«Mantén todo igual, pero…» protege lo que ya está bien.","Pídele que se critique y que lea como tu destinatario."]}]},{"id":"c-ia-m2-l5","titulo":"Lección 5 — Tu biblioteca de instrucciones","objetivo":"guardar y reutilizar tus mejores instrucciones para no empezar de cero cada vez.","bloques":[{"tipo":"texto","texto":"Si una instrucción te funcionó bien, <b>guárdala</b>. En un mes vas a tener una colección de plantillas para tus tareas repetitivas, y cada una te va a ahorrar tiempo todas las semanas. Es la diferencia entre «usar la IA de vez en cuando» y tenerla integrada a tu trabajo."},{"tipo":"titulo","texto":"Dónde guardarlas"},{"tipo":"lista","items":["<b>Una nota en tu celular</b> (Notas, Google Keep, OneNote) llamada «Mis instrucciones de IA».","<b>Un documento de Word o Google Docs</b> con un título por tarea.","<b>Las «instrucciones personalizadas» o «memoria» de tu herramienta</b>: muchas permiten guardar datos fijos sobre ti (tu puesto, tu tono) para que los use siempre. Búscalo en Configuración.","<b>Asistentes personalizados</b>: algunas herramientas permiten crear un asistente con instrucciones fijas (por ejemplo, «Mi redactor de correos»). Es opcional y avanzado."]},{"tipo":"titulo","texto":"Plantillas listas para tu biblioteca"},{"tipo":"plantilla","rotulo":"1. Contestar un correo","texto":"Eres mi asistente. Ayúdame a responder este correo. Mi objetivo es [qué quiero lograr]. Puntos que debo mencionar: [puntos]. Tono [cordial / firme / formal], en español de México, máximo [número] palabras.\n\nCorreo recibido:\n[pegar sin datos personales]"},{"tipo":"plantilla","rotulo":"2. Resumir un documento","texto":"Resume el documento adjunto para [quién lo va a leer]. Dame: 1) de qué trata en una frase, 2) los 5 puntos más importantes en viñetas, 3) cualquier fecha, cifra o compromiso que deba tener en cuenta, 4) qué acciones se derivan para mí."},{"tipo":"plantilla","rotulo":"3. Explicarme algo","texto":"Explícame [tema] como si no supiera nada, con un ejemplo de la vida diaria y otro de mi trabajo como [tu puesto]. Al final hazme 3 preguntas para comprobar que entendí."},{"tipo":"plantilla","rotulo":"4. Lluvia de ideas","texto":"Necesito ideas para [objetivo]. Contexto: [situación, presupuesto, restricciones]. Dame 10 ideas variadas, de las más sencillas a las más ambiciosas, en una tabla con: idea, costo (bajo/medio/alto), esfuerzo y por qué podría funcionar."},{"tipo":"plantilla","rotulo":"5. Revisar y mejorar un texto","texto":"Revisa este texto: corrige ortografía y gramática, hazlo más claro y directo, pero mantén mi estilo y no agregues información nueva. Después, en una lista aparte, dime qué cambiaste y por qué.\n\nTexto:\n[pegar]"},{"tipo":"destacado","texto":"<b>Usa corchetes [así]</b> para marcar lo que cambia cada vez. Al reutilizar la plantilla, solo reemplazas lo que está entre corchetes."},{"tipo":"pasos","rotulo":"Arma tu biblioteca hoy","pasos":["Crea una nota o documento llamado «Mis instrucciones de IA».","Copia las 5 plantillas de esta lección con el botón «Copiar».","Agrega tu párrafo de contexto personal (el que escribiste en la lección 2).","Cada vez que una instrucción te funcione muy bien, agrégala con un título claro.","Revisa tu herramienta: busca «Instrucciones personalizadas» o «Memoria» y guarda tu puesto y tu tono preferido."]},{"tipo":"reflexion","rotulo":"Tu plantilla propia","pregunta":"Escribe una plantilla para la tarea que más repites en tu trabajo, con corchetes en lo que cambia.","ayuda":"Eres… Tu tarea es… [dato que cambia]…"},{"tipo":"clave","items":["Lo que funciona, se guarda.","Corchetes [así] para lo que cambia.","Usa las instrucciones personalizadas de tu herramienta.","En un mes tendrás tu propio kit de productividad."]}]}],"quiz":{"titulo":"Evaluación del módulo 2","preguntas":[{"p":"Las cuatro partes de una buena instrucción son…","ops":["Papel, tarea, contexto y formato","Saludo, tema, firma y fecha","Idioma, largo, tono y color","Pregunta, respuesta, ejemplo y cierre"],"correcta":0},{"p":"¿Cuál parte suele mejorar más el resultado?","ops":["El saludo","El contexto","Escribir en mayúsculas","Decir «por favor»"],"correcta":1},{"p":"Para que un texto salga con el estilo exacto de tu marca, lo mejor es…","ops":["Describir el estilo","Pegar ejemplos reales y pedir que los imite","Pedir que sea creativo","Usar muchos emojis"],"correcta":1},{"p":"No sabes qué contexto darle. Puedes…","ops":["Pedirle que te haga preguntas antes de responder","Rendirte","Dar datos inventados","Escribir solo el tema"],"correcta":0},{"p":"Necesitas repartir tareas con responsables y fechas. Pides…","ops":["Un párrafo","Una tabla con columnas","Un poema","Una sola frase"],"correcta":1},{"p":"Para evitar que suene a traducción…","ops":["«En español de México, natural»","«En español neutro»","«Muy formal»","«En inglés»"],"correcta":0},{"p":"Te gusta todo el correo menos el cierre. Escribes…","ops":["«Hazlo otra vez»","«Mantén todo igual, pero cambia solo el cierre»","«Está mal»","Nada"],"correcta":1},{"p":"Para anticipar objeciones de un cliente…","ops":["«Léelo como si fueras el cliente y dime qué no le convencería»","«Hazlo más largo»","«Agrega emojis»","«Tradúcelo»"],"correcta":0},{"p":"En una plantilla, los corchetes [así] sirven para…","ops":["Decorar","Marcar lo que cambia cada vez","Que la IA los ignore","Poner títulos"],"correcta":1},{"p":"Las «instrucciones personalizadas» de tu herramienta sirven para…","ops":["Guardar datos fijos sobre ti y tu tono para todas las conversaciones","Borrar el historial","Pagar la suscripción","Cambiar el idioma del teclado"],"correcta":0}]}},{"id":"c-ia-m3","titulo":"Módulo 3 — Escribir y comunicar en minutos","resumen":"Escribir es lo que más tiempo consume en casi cualquier trabajo de oficina. En este módulo usas la IA para correos difíciles, mensajes a clientes, resúmenes y minutas, revisión de textos y comunicación en inglés, siempre manteniendo tu voz y tu criterio. Cinco lecciones y una evaluación.","lecciones":[{"id":"c-ia-m3-l1","titulo":"Lección 1 — Correos difíciles sin sufrir","objetivo":"redactar con IA correos de cobranza, disculpa, negativa y seguimiento que suenen profesionales y humanos.","bloques":[{"tipo":"texto","texto":"Los correos fáciles los escribes en un minuto. Los que cuestan son los difíciles: cobrarle a un cliente, decirle que no a tu jefe, disculparte por un error, reclamarle a un proveedor. Ahí es donde la IA más te ayuda, porque te da un borrador equilibrado cuando tú estás molesto, nervioso o sin palabras."},{"tipo":"titulo","texto":"La receta para cualquier correo difícil"},{"tipo":"lista","items":["<b>Qué pasó</b> — en dos frases, sin adjetivos.","<b>Qué quieres lograr</b> — que pague, que acepte, que no se enoje, que responda.","<b>Qué relación quieres cuidar</b> — «es un cliente importante», «es mi jefe directo».","<b>Qué puedes ofrecer y qué no</b> — «puedo dar 5 días más, no descuento».","<b>Tono</b> — firme, empático, formal, cercano."]},{"tipo":"plantilla","rotulo":"Correo de cobranza amable pero firme","texto":"Ayúdame a escribir un correo de cobranza. Contexto: un cliente tiene una factura vencida hace [número] días por [concepto]. Ya le recordamos [una vez / dos veces]. Es un cliente con el que queremos seguir trabajando. Objetivo: que pague o nos dé una fecha de pago esta semana. Podemos ofrecer [opción, p. ej. pagar en dos partes]. Tono cordial pero firme, sin amenazas. Máximo 120 palabras, en español de México."},{"tipo":"plantilla","rotulo":"Correo de disculpa por un error","texto":"Escribe un correo de disculpa a un cliente. Qué pasó: [error, p. ej. le enviamos el pedido incompleto]. Ya lo resolvimos así: [solución y fecha]. Como compensación ofrecemos [si aplica]. Quiero reconocer el error sin excusas largas, explicar la solución y cerrar con algo positivo. Máximo 130 palabras."},{"tipo":"plantilla","rotulo":"Decir que no sin quemar puentes","texto":"Necesito decirle que no a [quién] sobre [qué solicitud]. La razón real es [razón]. Quiero mantener buena relación y, si es posible, proponer una alternativa: [alternativa]. Escribe un correo breve, respetuoso y claro, que no deje la puerta abierta a malentendidos."},{"tipo":"comparar","titulo":"Escrito en caliente vs. con ayuda","malTitulo":"Escrito molesto","mal":"«Ya les he pedido TRES veces el pago y siguen sin responder. Si no pagan esta semana vamos a suspender el servicio. Es una falta de seriedad.»","bienTitulo":"Borrador con IA (y tu revisión)","bien":"«Hola, Laura. Te escribo sobre la factura 1234, vencida desde el 5 de mayo. Entiendo que pueden surgir imprevistos; ¿me ayudas a confirmar una fecha de pago esta semana? Si les facilita, podemos dividirla en dos pagos. Quedo atento. Saludos.»"},{"tipo":"destacado","texto":"<b>Tu criterio manda.</b> Lee siempre el borrador completo. Revisa que no prometa algo que no puedes cumplir (descuentos, fechas) y que los datos sean correctos. La IA escribe; tú firmas."},{"tipo":"practica","rotulo":"¿Qué agregarías a la instrucción?","preguntas":[{"p":"«Escribe un correo para reclamar a un proveedor.» Lo más importante que falta:","ops":["Qué falló, qué necesitas y para cuándo","El color del correo","Que use muchos signos de admiración"],"correcta":0},{"p":"El borrador ofrece un 20% de descuento que tú nunca mencionaste.","ops":["Lo mando, se ve bien","Le pido: «Quita el descuento; no puedo ofrecerlo»"],"correcta":1},{"p":"Estás muy enojado con un cliente. ¿Qué tono pides?","ops":["Agresivo, para que entienda","Firme pero cordial"],"correcta":1}]},{"tipo":"reflexion","rotulo":"Tu correo pendiente","pregunta":"¿Qué correo difícil tienes pendiente o se te presenta seguido? Escribe la instrucción completa con la receta de 5 puntos.","ayuda":"Qué pasó… Qué quiero lograr… Relación… Puedo ofrecer… Tono…"},{"tipo":"clave","items":["Receta: qué pasó, objetivo, relación, qué puedes ofrecer, tono.","Úsala cuando estés molesto: te da un borrador equilibrado.","Revisa promesas y datos antes de enviar."]}]},{"id":"c-ia-m3-l2","titulo":"Lección 2 — Mensajes a clientes por WhatsApp y redes","objetivo":"crear mensajes cortos y efectivos para WhatsApp, publicaciones y respuestas a comentarios.","bloques":[{"tipo":"texto","texto":"Un mensaje de WhatsApp o una publicación tiene otras reglas que un correo: se lee en el celular, en segundos, entre otros cien mensajes. Tiene que ir al grano, sonar humano y decir qué hacer después. La IA te ayuda a lograrlo si le das esas reglas."},{"tipo":"tabla","titulo":"Reglas del mensaje corto","encabezados":["Regla","Por qué"],"filas":[["Máximo 3–4 renglones","Nadie lee párrafos en el celular."],["Lo importante en la primera línea","Es lo único que se ve en la notificación."],["Una sola acción clara","«Responde SÍ para apartar», «Agenda aquí»."],["Tono de persona, no de empresa","Genera confianza y respuesta."],["Emojis con medida","1 a 3 ayudan; 10 parecen spam."]]},{"tipo":"plantilla","rotulo":"Mensajes de WhatsApp para clientes","texto":"Escribe 3 versiones de un mensaje de WhatsApp para [tipo de clientes] sobre [tema: promoción, recordatorio, aviso]. Reglas: máximo 4 renglones, lo más importante en la primera línea, una sola acción clara al final ([acción]), tono cercano en español de México, máximo 2 emojis."},{"tipo":"plantilla","rotulo":"Calendario de publicaciones","texto":"Tengo un negocio de [giro] en [ciudad]. Mis clientes son [descripción]. Hazme un calendario de 8 publicaciones para redes sociales para las próximas 4 semanas, en una tabla con: fecha sugerida, tipo (promoción, consejo, detrás de cámaras, testimonio), texto de la publicación (máximo 60 palabras) e idea de foto."},{"tipo":"plantilla","rotulo":"Responder un comentario negativo","texto":"Un cliente dejó este comentario público en nuestra página: \"[comentario]\". Escribe una respuesta pública breve (máximo 50 palabras), empática, sin discutir, que reconozca su molestia y lo invite a resolverlo por mensaje privado."},{"tipo":"destacado","texto":"<b>Mensajes masivos con cuidado:</b> enviar mensajes promocionales a personas que no te dieron su número para eso molesta y puede bloquear tu cuenta de WhatsApp Business. La IA te ayuda a escribir el mensaje; a quién se lo mandas es tu responsabilidad."},{"tipo":"practica","rotulo":"¿Cuál funciona mejor en WhatsApp?","preguntas":[{"p":"Recordatorio de cita:","ops":["«Estimado cliente, por medio del presente le recordamos que tiene usted una cita programada…»","«Hola, Ana 👋 Te recordamos tu cita mañana jueves a las 10:00. ¿Nos confirmas con un SÍ?»"],"correcta":1},{"p":"La primera línea de una promoción debe…","ops":["Saludar con formalidad","Decir la oferta y la fecha límite","Contar la historia de la empresa"],"correcta":1},{"p":"Un cliente se queja en público. La mejor respuesta pública…","ops":["Explica por qué el cliente está equivocado","Reconoce, se disculpa si aplica y lo invita a resolverlo en privado","No responde"],"correcta":1}]},{"tipo":"reflexion","rotulo":"Tu mensaje","pregunta":"Escribe con ayuda de la IA un mensaje real que necesites enviar a clientes o compañeros esta semana. Pégalo aquí ya revisado por ti.","ayuda":"Hola… "},{"tipo":"clave","items":["Corto, lo importante primero, una acción clara.","Tono de persona; emojis con medida.","Pide varias versiones y elige."]}]},{"id":"c-ia-m3-l3","titulo":"Lección 3 — Resúmenes y minutas de juntas","objetivo":"resumir documentos largos y convertir tus notas de una junta en una minuta con acuerdos y responsables.","bloques":[{"tipo":"texto","texto":"Resumir es de las tareas donde la IA ahorra más tiempo: un documento de 30 páginas, un hilo de 40 correos o tus notas desordenadas de una junta se convierten en una página clara. La clave es decirle <b>para qué</b> quieres el resumen."},{"tipo":"titulo","texto":"Resumir documentos"},{"tipo":"pasos","rotulo":"Cómo hacerlo","pasos":["Adjunta el documento (PDF, Word) con el clip o el botón +, o pega el texto. Quita datos personales sensibles si los hay.","Di quién va a leer el resumen y para qué: «para decidir si firmamos», «para explicárselo a mi equipo».","Pide una estructura: de qué trata, puntos clave, fechas y cifras, acciones.","Pregunta cosas específicas: «¿qué dice sobre penalizaciones?», «¿hay algo que me deba preocupar?».","Verifica en el documento original cualquier cifra, fecha o cláusula que vayas a usar para decidir."]},{"tipo":"plantilla","rotulo":"Resumen para decidir","texto":"Resume el documento adjunto para alguien que tiene que decidir [decisión]. Estructura: 1) En una frase, de qué se trata. 2) Los 5 puntos más importantes. 3) Riesgos o letras chiquitas que debo revisar. 4) Fechas, montos y obligaciones. 5) Preguntas que debería hacer antes de decidir. Cita la página o sección de donde sale cada punto importante.","nota":"Pedirle que cite la página te permite comprobar rápido en el original."},{"tipo":"titulo","texto":"De notas desordenadas a minuta"},{"tipo":"texto","texto":"Durante una junta, anota como puedas: palabras sueltas, nombres, fechas. Al terminar, pégaselas a la IA. Algunas herramientas de videollamada (Teams, Meet, Zoom) ya generan transcripciones o resúmenes automáticos; si tu empresa lo permite, también puedes usar esa transcripción."},{"tipo":"plantilla","rotulo":"Minuta a partir de notas","texto":"Convierte estas notas de junta en una minuta formal. Incluye: fecha, asistentes, temas tratados (en viñetas breves), acuerdos, y una tabla de pendientes con columnas: tarea, responsable, fecha límite. Si algo de mis notas no es claro, márcalo como [por confirmar] en lugar de suponer.\n\nNotas:\n[pegar notas]"},{"tipo":"comparar","titulo":"Tus notas → minuta","malTitulo":"Tus notas","mal":"lunes junta ventas / pepe dice inventario bajo sucursal centro / ana hace pedido antes del jueves / precio nuevo desde 1 junio?? / siguiente junta 15","bienTitulo":"Minuta generada","bien":"<b>Acuerdos:</b> reabastecer sucursal Centro.<br><b>Pendientes:</b> Ana — hacer pedido — jueves.<br><b>Por confirmar:</b> fecha del nuevo precio (¿1 de junio?).<br><b>Próxima junta:</b> día 15."},{"tipo":"destacado","texto":"<b>Fíjate en «[por confirmar]».</b> Pedirle que marque lo dudoso en lugar de inventar es lo que hace confiable la minuta. Sin esa instrucción, la IA podría «completar» datos que nadie dijo."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Para que un resumen sirva, lo más importante es decirle…","ops":["Para quién y para qué es","Que use palabras difíciles","Que sea muy largo"],"correcta":0},{"p":"El resumen dice que la penalización es de 10%. Vas a usar ese dato para negociar.","ops":["Lo uso tal cual","Lo compruebo en la cláusula original"],"correcta":1},{"p":"Tus notas dicen «¿viernes o lunes?». En la minuta la IA debe…","ops":["Elegir uno","Marcarlo como por confirmar"],"correcta":1}]},{"tipo":"reflexion","rotulo":"Tu próxima junta","pregunta":"En tu siguiente junta toma notas rápidas y conviértelas en minuta con la plantilla. Anota aquí cuánto tiempo te tomó comparado con hacerla a mano.","ayuda":"Antes me tardaba… Con IA…"},{"tipo":"clave","items":["Di para quién y para qué es el resumen.","Pide citas de página para verificar rápido.","Minutas: acuerdos + tabla de pendientes + [por confirmar]."]}]},{"id":"c-ia-m3-l4","titulo":"Lección 4 — Revisar y mejorar tus textos sin perder tu voz","objetivo":"usar la IA como editor: corregir ortografía, aclarar y ajustar el tono manteniendo tu estilo.","bloques":[{"tipo":"texto","texto":"No siempre necesitas que la IA escriba por ti. Muchas veces lo mejor es que <b>tú escribas</b> y ella te ayude a pulir: corregir faltas, ordenar ideas, quitar lo que sobra. Así el texto sigue sonando a ti, que es lo que tus clientes y compañeros conocen."},{"tipo":"tabla","titulo":"Niveles de edición","encabezados":["Nivel","Qué pedir","Cuándo"],"filas":[["Ligero","«Solo corrige ortografía y puntuación. No cambies nada más.»","Cuando el texto ya está bien."],["Medio","«Hazlo más claro y directo, mantén mi estilo, no agregues información.»","Cuando se siente enredado."],["Profundo","«Reorganízalo para que la idea principal vaya primero y sobre lo que sobra.»","Cuando no se entiende."]]},{"tipo":"plantilla","rotulo":"Editor que explica","texto":"Corrige este texto en nivel [ligero / medio / profundo]. Mantén mi forma de escribir y no agregues información nueva. Después, en una lista, dime los cambios principales y por qué, para que yo aprenda.\n\nTexto:\n[pegar]","nota":"La lista de cambios te enseña a escribir mejor con el tiempo: vas a notar que tus errores se repiten."},{"tipo":"titulo","texto":"Ajustar el tono"},{"tipo":"relacionar","rotulo":"¿Qué instrucción usarías?","pares":[["Suena grosero sin querer","«Suavízalo sin perder la firmeza»"],["Suena inseguro","«Hazlo más seguro y directo, quita disculpas innecesarias»"],["Es para el director","«Hazlo más ejecutivo: conclusión primero, sin rodeos»"],["Es para un cliente mayor","«Hazlo más formal y cálido, trato de usted»"]]},{"tipo":"comparar","titulo":"Quitar lo que sobra","malTitulo":"Original","mal":"«Bueno, pues quería comentarles que, como algunos ya sabrán, el día de mañana, que es viernes, no vamos a poder abrir la oficina debido a que van a estar haciendo trabajos de mantenimiento en el edificio.»","bienTitulo":"Editado","bien":"«Mañana viernes la oficina estará cerrada por mantenimiento del edificio.»"},{"tipo":"destacado","texto":"<b>Cuidado con la «voz de IA».</b> Si aceptas todo lo que propone, tus textos empiezan a sonar iguales a los de todos: «¡Excelente pregunta!», «es fundamental destacar», «en el dinámico mundo de…». Si notas esas frases, pídele que las quite o quítalas tú."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Tu texto ya está bien, solo quieres evitar faltas.","ops":["Edición ligera: solo ortografía","Edición profunda"],"correcta":0},{"p":"La IA «mejoró» tu correo y agregó una promesa que no hiciste.","ops":["Está bien","Le pido que no agregue información nueva y lo reviso"],"correcta":1},{"p":"¿Para qué pedir la lista de cambios?","ops":["Para aprender de mis errores","No sirve"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Tus errores frecuentes","pregunta":"Pasa por el «editor que explica» 2 o 3 textos tuyos. ¿Qué errores se repiten? Anótalos aquí para cuidarlos.","ayuda":"Suelo… Me falta… Uso demasiado…"},{"tipo":"clave","items":["Tú escribes, la IA pule: sigue sonando a ti.","Elige el nivel: ligero, medio, profundo.","Pide la lista de cambios para aprender.","Quita las frases de «voz de IA»."]}]},{"id":"c-ia-m3-l5","titulo":"Lección 5 — Comunicarte en inglés con apoyo de la IA","objetivo":"traducir correos y documentos con buena calidad, y usar la IA para prepararte antes de una llamada en inglés.","bloques":[{"tipo":"texto","texto":"Si en tu trabajo te llegan correos en inglés o tienes proveedores o clientes del extranjero, la IA es mucho más que un traductor: te ayuda a entender el tono, a responder de forma natural y hasta a practicar antes de una llamada."},{"tipo":"titulo","texto":"Traducir bien (no palabra por palabra)"},{"tipo":"plantilla","rotulo":"Traducir un correo que recibiste","texto":"Traduce este correo al español. Después dime en 2 frases qué me está pidiendo, qué tono tiene (amable, molesto, urgente) y si hay algo que debería contestar.\n\n[pegar correo]"},{"tipo":"plantilla","rotulo":"Responder en inglés","texto":"Escribí mi respuesta en español. Tradúcela a un inglés profesional y natural, como lo escribiría una persona de negocios en Estados Unidos. Mantén el mensaje exacto; no agregues compromisos. Después, dame la traducción literal al español de tu versión en inglés para confirmar que dice lo que quiero.\n\nMi respuesta:\n[pegar]","nota":"La «vuelta» al español es tu forma de verificar que la traducción no cambió el sentido."},{"tipo":"destacado","texto":"<b>Falsos amigos:</b> la IA traduce bien, pero revisa palabras como <i>actually</i> (en realidad, no «actualmente»), <i>eventually</i> (con el tiempo, no «eventualmente») o <i>assist</i> (ayudar, no «asistir»). Si algo te suena raro en la vuelta al español, pregunta."},{"tipo":"titulo","texto":"Prepararte para una llamada o junta en inglés"},{"tipo":"plantilla","rotulo":"Ensayo de conversación","texto":"Mañana tengo una llamada en inglés con [quién] sobre [tema]. Mi nivel de inglés es [básico / intermedio]. 1) Dame 10 frases útiles que probablemente necesite, con su traducción. 2) Luego haz el papel de [la otra persona] y conversa conmigo en inglés, una pregunta a la vez. Si me equivoco, corrígeme amablemente en español al final de cada respuesta.","nota":"Con el micrófono de tu celular puedes hacer este ensayo hablando en voz alta."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Para qué pedir la traducción de regreso al español?","ops":["Para verificar que el sentido no cambió","Para que tarde más","No sirve"],"correcta":0},{"p":"«Actually» significa…","ops":["Actualmente","En realidad"],"correcta":1},{"p":"Tienes una junta en inglés mañana. Una buena forma de prepararte es…","ops":["Pedirle a la IA que haga el papel de la otra persona y practicar","Traducir todo en el momento"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Tu caso","pregunta":"¿En qué situación de tu trabajo te sirve comunicarte en inglés? Escribe cómo usarías una de las plantillas de esta lección.","ayuda":"Me llegan correos de… Tengo llamadas con…"},{"tipo":"clave","items":["Pide traducción + tono + qué te piden.","Al responder, pide la vuelta al español para verificar.","Ensaya llamadas con la IA haciendo el otro papel."]}]}],"quiz":{"titulo":"Evaluación del módulo 3","preguntas":[{"p":"Para un correo difícil, ¿qué NO es parte de la receta?","ops":["Qué pasó","Qué quieres lograr","Qué puedes ofrecer","El color de la letra"],"correcta":3},{"p":"El borrador ofrece algo que no puedes cumplir. Tú…","ops":["Lo mandas","Pides que lo quite y revisas","Lo dejas en borrador para siempre","Lo reenvías a tu jefe"],"correcta":1},{"p":"La regla más importante de un mensaje de WhatsApp es…","ops":["Que sea muy largo","Lo importante en la primera línea","Usar 10 emojis","Empezar con «Estimado»"],"correcta":1},{"p":"A un comentario negativo público conviene responder…","ops":["Discutiendo","Con empatía y ofreciendo resolver en privado","Borrándolo siempre","Con sarcasmo"],"correcta":1},{"p":"Para que un resumen sea útil, dile…","ops":["Para quién y para qué es","Que use tecnicismos","Que ignore las cifras","Nada más"],"correcta":0},{"p":"En una minuta, lo que no quedó claro en tus notas debe…","ops":["Inventarse","Marcarse como [por confirmar]","Borrarse","Adivinarse"],"correcta":1},{"p":"Si solo quieres corregir ortografía, pides…","ops":["Edición ligera","Reescritura total","Traducción","Un resumen"],"correcta":0},{"p":"¿Por qué pedir la lista de cambios al editar?","ops":["Para aprender tus errores frecuentes","Para que tarde más","Para gastar menos","No sirve"],"correcta":0},{"p":"Al traducir tu respuesta al inglés, verificas el sentido pidiendo…","ops":["La traducción de regreso al español","Más emojis","Un resumen","Que lo haga más largo"],"correcta":0},{"p":"«Eventually» en inglés significa…","ops":["Eventualmente (de vez en cuando)","Con el tiempo, finalmente","Evento","Nunca"],"correcta":1}]}},{"id":"c-ia-m4","titulo":"Módulo 4 — Datos, Excel y organización","resumen":"La IA no solo escribe: también ordena información, te ayuda con fórmulas de Excel, encuentra patrones en tus números y organiza tu semana. En este módulo aprendes a usarla con datos sin caer en su punto débil: los cálculos. Cinco lecciones y una evaluación.","lecciones":[{"id":"c-ia-m4-l1","titulo":"Lección 1 — De información desordenada a tabla","objetivo":"convertir listas, correos o notas desordenadas en tablas limpias que puedes pegar en Excel.","bloques":[{"tipo":"texto","texto":"¿Tienes una lista de clientes pegada de un chat, pedidos que llegaron por WhatsApp o datos regados en un correo? Ordenarlos a mano toma una hora. Con la IA toma un minuto. Es una de las funciones que más tiempo ahorra y de las menos conocidas."},{"tipo":"comparar","titulo":"Antes y después","malTitulo":"Pedidos que llegaron por WhatsApp","mal":"«soy lupita quiero 3 cajas de galletas de nuez para el viernes»<br>«Buen día, de parte de Ferretería Ruiz: 10 paquetes de tornillos 1/2 y 2 martillos, entregar lunes»<br>«hola me mandas 2 de galletas de chocolate? mañana porfa. Beto»","bienTitulo":"Tabla generada","bien":"<table style=\"width:100%;font-size:.8rem;min-width:0\"><tr><td><b>Cliente</b></td><td><b>Producto</b></td><td><b>Cant.</b></td><td><b>Entrega</b></td></tr><tr><td>Lupita</td><td>Galletas de nuez (caja)</td><td>3</td><td>viernes</td></tr><tr><td>Ferretería Ruiz</td><td>Tornillos 1/2 (paq.)</td><td>10</td><td>lunes</td></tr><tr><td>Ferretería Ruiz</td><td>Martillo</td><td>2</td><td>lunes</td></tr><tr><td>Beto</td><td>Galletas de chocolate</td><td>2</td><td>mañana</td></tr></table>"},{"tipo":"plantilla","rotulo":"Ordenar información en tabla","texto":"Organiza la siguiente información en una tabla con estas columnas: [columna 1], [columna 2], [columna 3]. Una fila por cada [registro]. Si un dato no aparece, deja la celda vacía; no lo inventes. Al final dime qué registros tenían información incompleta o confusa.\n\nInformación:\n[pegar]"},{"tipo":"destacado","texto":"<b>Dos reglas de oro con datos:</b> 1) «Si un dato no aparece, deja la celda vacía; no lo inventes». 2) Revisa el conteo: si pegaste 40 pedidos, la tabla debe tener 40 filas. Si falta alguno, díselo."},{"tipo":"pasos","rotulo":"Pasar la tabla a Excel","pasos":["Cuando la IA te muestre la tabla, selecciónala completa con el mouse (o usa el botón de copiar si aparece).","Abre Excel o Google Sheets y haz clic en la celda A1.","Pega con Ctrl + V (Cmd + V en Mac).","Si todo quedó en una sola columna, pídele a la IA: «Dámelo separado por tabulaciones» o «en formato CSV» y vuelve a pegar.","Revisa rápido que las columnas coincidan con los encabezados."]},{"tipo":"titulo","texto":"Otros usos del mismo truco"},{"tipo":"lista","items":["<b>Limpiar una lista:</b> «Quita duplicados, pon los nombres con mayúscula inicial y ordénalos alfabéticamente.»","<b>Separar datos:</b> «Separa nombre, apellido y ciudad en columnas distintas.»","<b>Clasificar:</b> «Agrega una columna que clasifique cada gasto en: renta, sueldos, insumos, servicios u otros.»","<b>Leer una foto:</b> tómale foto a una lista impresa o a un ticket y pídele que la pase a tabla. Revisa bien los números."]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Pegaste 25 registros y la tabla tiene 23 filas. ¿Qué haces?","ops":["La uso así","Le digo que faltan 2 y que revise"],"correcta":1},{"p":"Un pedido no dice la fecha de entrega. En la tabla debe…","ops":["Quedar vacía o marcada","Poner la fecha que la IA suponga"],"correcta":0},{"p":"La tabla se pegó en Excel toda en una columna.","ops":["Pido formato separado por tabulaciones o CSV","La escribo a mano"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Tu información desordenada","pregunta":"¿Qué información te llega desordenada en tu trabajo? Escribe qué columnas tendría la tabla ideal.","ayuda":"Me llegan… por… Columnas: …"},{"tipo":"clave","items":["Pega lo desordenado, pide columnas específicas.","«No inventes datos; deja vacío lo que falte.»","Revisa el conteo de filas.","La tabla se pega directo en Excel."]}]},{"id":"c-ia-m4-l2","titulo":"Lección 2 — Fórmulas de Excel sin memorizar","objetivo":"pedirle a la IA la fórmula exacta que necesitas, entenderla y aplicarla en tu hoja.","bloques":[{"tipo":"texto","texto":"Excel puede hacer casi cualquier cálculo, pero recordar cómo se escribe cada fórmula es otra historia. La IA es excelente para esto: le describes lo que quieres <b>con palabras</b> y te da la fórmula lista para pegar, con explicación."},{"tipo":"titulo","texto":"Cómo pedir una fórmula"},{"tipo":"lista","items":["<b>Qué tienes:</b> «En la columna A tengo nombres de vendedores, en B las ventas, desde la fila 2 hasta la 150.»","<b>Qué quieres:</b> «Quiero saber el total vendido por Juan.»","<b>Dónde:</b> «La fórmula va en la celda E2.»","<b>Tu programa:</b> «Uso Excel en español» (los nombres de funciones cambian según el idioma: SUMA / SUM)."]},{"tipo":"plantilla","rotulo":"Pedir una fórmula","texto":"Uso Excel en español. En mi hoja tengo: [describe columnas y filas, p. ej. A = fecha, B = cliente, C = monto, de la fila 2 a la 500]. Necesito [lo que quieres calcular]. La fórmula va en la celda [celda]. Dame la fórmula lista para pegar y explícame en palabras sencillas qué hace cada parte."},{"tipo":"tabla","titulo":"Fórmulas que más se piden","encabezados":["Necesito…","Fórmula (Excel en español)"],"filas":[["Sumar una columna","<code>=SUMA(B2:B150)</code>"],["Sumar solo lo de un vendedor","<code>=SUMAR.SI(A2:A150,\"Juan\",B2:B150)</code>"],["Contar cuántas ventas hizo","<code>=CONTAR.SI(A2:A150,\"Juan\")</code>"],["Promedio","<code>=PROMEDIO(B2:B150)</code>"],["Buscar el precio de un producto en otra tabla","<code>=BUSCARX(E2,Productos!A:A,Productos!C:C)</code>"],["Poner «Vencida» si la fecha ya pasó","<code>=SI(C2&lt;HOY(),\"Vencida\",\"Al corriente\")</code>"]],"nota":"En Google Sheets y en Excel en inglés los nombres cambian (SUM, SUMIF, COUNTIF, AVERAGE, XLOOKUP, IF, TODAY). Dile a la IA cuál usas. En algunas configuraciones regionales se usa punto y coma (;) en lugar de coma (,) entre los argumentos."},{"tipo":"destacado","texto":"<b>Pruébala siempre con un caso que conozcas.</b> Si la fórmula dice que Juan vendió $48,000, filtra a mano a Juan y comprueba. Si coincide, confía en ella para el resto. Si no, dile a la IA qué resultado esperabas."},{"tipo":"titulo","texto":"Cuando sale error"},{"tipo":"relacionar","rotulo":"¿Qué significa el error?","pares":[["#¿NOMBRE?","Excel no reconoce la función (idioma o mal escrita)"],["#N/D","No encontró lo que buscabas"],["#¡VALOR!","Mezclaste texto con números"],["#¡DIV/0!","Estás dividiendo entre cero o una celda vacía"]]},{"tipo":"plantilla","rotulo":"Arreglar una fórmula","texto":"Esta fórmula me da el error [error]: [pega la fórmula]. Mis datos están así: [describe]. ¿Por qué falla y cómo la corrijo?"},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Para que la IA te dé la fórmula correcta, lo más importante es decirle…","ops":["Dónde están tus datos y qué quieres calcular","Que sea rápida","Tu nombre"],"correcta":0},{"p":"Te sale #¿NOMBRE? con una fórmula SUMIF en Excel en español.","ops":["Está en inglés; debe ser SUMAR.SI","Faltan datos"],"correcta":0},{"p":"¿Cómo compruebas que la fórmula funciona?","ops":["Con un caso cuyo resultado ya conoces","Confiando en la IA"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Tu fórmula","pregunta":"Piensa en un cálculo que haces a mano en Excel (o con calculadora). Escribe cómo se lo pedirías a la IA con la plantilla.","ayuda":"Uso Excel en… En mi hoja tengo… Necesito…"},{"tipo":"clave","items":["Describe columnas, filas, qué calcular y dónde va.","Di si usas Excel en español, en inglés o Google Sheets.","Prueba con un caso conocido.","Pega el error y pide que lo explique."]}]},{"id":"c-ia-m4-l3","titulo":"Lección 3 — Analizar números y sacar conclusiones","objetivo":"usar la IA para interpretar datos y encontrar hallazgos, sin confiarle los cálculos que debe hacer Excel.","bloques":[{"tipo":"texto","texto":"Aquí está el punto débil de las IA de texto: <b>los cálculos</b>. Como predicen texto, pueden equivocarse al sumar 50 números o al calcular un porcentaje complicado, y te lo presentan con total seguridad. Pero son muy buenas para <b>interpretar</b>: ver tendencias, proponer explicaciones y hacer las preguntas correctas."},{"tipo":"comparar","titulo":"Dividir el trabajo","malTitulo":"No le pidas","mal":"«Suma estas 80 facturas y dime el total exacto.»<br>«Calcula el IVA de cada partida.»","bienTitulo":"Sí le pides","bien":"«Aquí están mis ventas por mes (ya calculadas en Excel). ¿Qué tendencias ves? ¿Qué meses se salen de lo normal y qué podría explicarlo?»<br>«Dame 5 preguntas que debería hacerme sobre estos números.»","nota":"<b>Excel calcula, la IA interpreta.</b> Algunas herramientas pueden ejecutar cálculos con código cuando les subes un archivo; aun así, comprueba los totales importantes."},{"tipo":"plantilla","rotulo":"Analizar un resumen de datos","texto":"Te comparto un resumen de [ventas / gastos / asistencia] de [periodo]. Los totales ya están calculados, no los recalcules.\n[pegar tabla resumen]\n\n1) ¿Qué tendencias ves? 2) ¿Qué valores se salen de lo normal? 3) ¿Qué posibles explicaciones hay? 4) ¿Qué 3 acciones recomendarías? 5) ¿Qué dato adicional necesitaría para estar más seguro?"},{"tipo":"titulo","texto":"Ejemplo"},{"tipo":"tabla","titulo":"Ventas de una cafetería (miles de pesos)","encabezados":["Mes","Ventas","Clientes"],"filas":[["Enero","180","3,100"],["Febrero","176","3,050"],["Marzo","210","3,300"],["Abril","150","2,400"],["Mayo","205","3,350"]]},{"tipo":"practica","rotulo":"Piensa como analista","preguntas":[{"p":"¿Qué mes se sale de lo normal?","ops":["Marzo","Abril","Mayo"],"correcta":1,"explica":"Abril bajó ventas y clientes casi 30% respecto a marzo."},{"p":"Una buena pregunta para la IA sobre abril sería…","ops":["«¿Qué podría explicar la caída de abril en una cafetería?»","«Suma las ventas»"],"correcta":0,"explica":"Te sugerirá cosas como vacaciones de Semana Santa, obras en la calle, un competidor nuevo… Tú confirmas cuál aplica."},{"p":"Si la IA dice que el promedio es 184.2, ¿qué haces antes de ponerlo en tu reporte?","ops":["Lo compruebo con =PROMEDIO en Excel","Lo copio directo"],"correcta":0,"explica":"(180+176+210+150+205)/5 = 184.2. Esta vez está bien, pero la comprobación toma 10 segundos."}]},{"tipo":"destacado","texto":"<b>Las explicaciones de la IA son hipótesis, no hechos.</b> Si dice «la caída de abril probablemente se deba a Semana Santa», es una idea razonable que tú debes confirmar con lo que sabes del negocio."},{"tipo":"reflexion","rotulo":"Tus números","pregunta":"¿Qué números revisas en tu trabajo cada semana o mes? Escribe 3 preguntas que le harías a la IA sobre ellos.","ayuda":"Reviso… Le preguntaría…"},{"tipo":"clave","items":["Excel calcula; la IA interpreta.","Dile que no recalcule los totales.","Sus explicaciones son hipótesis: tú confirmas."]}]},{"id":"c-ia-m4-l4","titulo":"Lección 4 — Organiza tu semana y tus proyectos","objetivo":"usar la IA para priorizar pendientes, planear tu semana y dividir un proyecto en pasos.","bloques":[{"tipo":"texto","texto":"Cuando tienes 20 pendientes en la cabeza, lo más difícil no es hacerlos: es decidir por dónde empezar. La IA es muy buena para ordenar, priorizar y dividir tareas grandes en pasos pequeños."},{"tipo":"titulo","texto":"Priorizar"},{"tipo":"plantilla","rotulo":"Vaciar la cabeza y priorizar","texto":"Estos son todos mis pendientes, sin orden:\n[pega o dicta todo lo que tengas]\n\nMi horario disponible esta semana es [horas / días]. Lo más importante para mi jefe este mes es [objetivo]. Clasifícalos en una tabla con: pendiente, urgencia (alta/media/baja), importancia (alta/media/baja), tiempo estimado y día sugerido. Después dime cuáles 3 hago primero y cuáles podría delegar o eliminar.","nota":"Dictarlo con el micrófono en el camión o antes de dormir funciona muy bien."},{"tipo":"tabla","titulo":"La matriz urgente / importante","encabezados":["","Urgente","No urgente"],"filas":[["<b>Importante</b>","Hazlo hoy","Agéndalo (aquí está lo que más te hace crecer)"],["<b>No importante</b>","Delégalo o hazlo rápido","Elimínalo"]]},{"tipo":"titulo","texto":"Dividir un proyecto grande"},{"tipo":"plantilla","rotulo":"De proyecto a plan","texto":"Tengo que [proyecto] para el [fecha]. Participan [personas / roles]. Divide el proyecto en fases y tareas concretas, en una tabla con: fase, tarea, responsable sugerido, duración estimada y fecha límite, contando hacia atrás desde la entrega. Señala qué tareas dependen de otras y cuáles son los riesgos principales."},{"tipo":"comparar","titulo":"Tarea gigante vs. primer paso","malTitulo":"En tu lista","mal":"«Organizar la posada de la oficina»","bienTitulo":"Después de la IA","bien":"1. Definir presupuesto con RH (lunes)<br>2. Encuesta de fecha al equipo (martes)<br>3. Cotizar 3 lugares (miércoles–viernes)<br>4. Reservar lugar (lunes siguiente)<br>…"},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Algo es importante pero no urgente (ej. aprender una nueva herramienta). ¿Qué haces?","ops":["Lo agendo","Lo elimino","Lo hago ya aunque haya urgencias"],"correcta":0},{"p":"Para que la IA priorice bien, ¿qué dato ayuda más?","ops":["Tus objetivos y tu tiempo disponible","Tu color favorito"],"correcta":0},{"p":"«Hacer el reporte anual» te paraliza. ¿Qué le pides a la IA?","ops":["Que lo divida en pasos pequeños con fechas","Que lo haga completo sin datos"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Tu semana","pregunta":"Haz el ejercicio de «vaciar la cabeza» con todos tus pendientes reales. Escribe aquí las 3 tareas que la IA te recomendó hacer primero y si estás de acuerdo.","ayuda":"1. … 2. … 3. …"},{"tipo":"clave","items":["Vacía todos tus pendientes y pide prioridades con tu contexto.","Urgente/importante: hazlo, agéndalo, delégalo o elimínalo.","Divide proyectos grandes en tareas con fecha y responsable."]}]},{"id":"c-ia-m4-l5","titulo":"Lección 5 — Ideas y decisiones: tu compañero para pensar","objetivo":"usar la IA para generar ideas, ver un problema desde varios ángulos y tomar mejores decisiones.","bloques":[{"tipo":"texto","texto":"La IA no decide por ti, pero es un excelente compañero para pensar: genera opciones que no se te habían ocurrido, te hace ver riesgos y te obliga a ordenar tus argumentos. Es como tener a alguien con quien platicar un problema a cualquier hora."},{"tipo":"titulo","texto":"Tres técnicas"},{"tipo":"plantilla","rotulo":"1. Muchas ideas, luego filtrar","texto":"Necesito ideas para [objetivo]. Dame 15 ideas muy variadas, incluyendo algunas poco convencionales. Luego elige las 3 más viables para [restricciones: presupuesto, tiempo, equipo] y explica por qué."},{"tipo":"plantilla","rotulo":"2. Pros, contras y riesgos","texto":"Estoy decidiendo entre [opción A] y [opción B]. Contexto: [situación]. Haz una tabla con pros, contras, costos y riesgos de cada opción. Después hazme 5 preguntas que me ayuden a decidir. No me digas qué elegir hasta que responda."},{"tipo":"plantilla","rotulo":"3. Abogado del diablo","texto":"Esta es mi idea: [idea]. Actúa como un crítico exigente pero justo: dime las 5 razones más fuertes por las que podría fracasar y qué haría para prevenir cada una."},{"tipo":"destacado","texto":"<b>Por qué «no me digas qué elegir hasta que responda»:</b> si la IA decide primero, tiendes a quedarte con su respuesta. Al contestar sus preguntas, tú ordenas tu propio criterio. La decisión y la responsabilidad son tuyas."},{"tipo":"comparar","titulo":"Pedir la respuesta vs. pensar con la IA","malTitulo":"Delegar la decisión","mal":"«¿Debo abrir una segunda sucursal?»<br>→ Una respuesta genérica sin conocer tu negocio.","bienTitulo":"Pensar juntos","bien":"«Estoy evaluando abrir segunda sucursal. Vendemos X, tenemos Y de ahorro, la zona es Z. Hazme las preguntas que haría un asesor de negocios antes de recomendar algo.»"},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Quién toma la decisión final?","ops":["La IA","Tú"],"correcta":1},{"p":"Quieres encontrar los puntos débiles de tu propuesta antes de presentarla.","ops":["Técnica del abogado del diablo","Pedir que la haga más larga"],"correcta":0},{"p":"La IA te da 15 ideas y 12 no sirven. ¿Falló?","ops":["Sí, es inútil","No: el objetivo era tener muchas opciones y quedarte con las mejores"],"correcta":1}]},{"tipo":"reflexion","rotulo":"Tu decisión pendiente","pregunta":"Piensa en una decisión de trabajo que tengas pendiente. Usa la técnica 2 y escribe aquí qué pregunta de la IA te hizo pensar algo nuevo.","ayuda":"Estoy decidiendo… La pregunta que más me sirvió fue…"},{"tipo":"clave","items":["Primero cantidad de ideas, luego filtra.","Tabla de pros, contras y riesgos + preguntas para ti.","Abogado del diablo para fortalecer tus propuestas.","Tú decides."]}]}],"quiz":{"titulo":"Evaluación del módulo 4","preguntas":[{"p":"Al pedir que ordene datos en una tabla, una instrucción clave es…","ops":["«Si falta un dato, no lo inventes»","«Hazlo bonito»","«Agrega datos de ejemplo»","«Hazlo en párrafo»"],"correcta":0},{"p":"Pegaste 40 registros y salen 38 filas. Tú…","ops":["Lo usas así","Le avisas que faltan 2","Borras 2 más","Cambias de herramienta"],"correcta":1},{"p":"Para pedir una fórmula de Excel conviene decir…","ops":["Qué columnas tienes, qué calcular y dónde va","Solo el nombre del archivo","Tu contraseña de Office","Nada, que adivine"],"correcta":0},{"p":"#¿NOMBRE? en Excel suele significar…","ops":["La función no se reconoce (idioma o mal escrita)","Dividir entre cero","No encontró el valor","Mezclaste texto"],"correcta":0},{"p":"¿Cómo compruebas una fórmula nueva?","ops":["Con un caso cuyo resultado conoces","Confiando","Preguntando otra vez","No se puede"],"correcta":0},{"p":"El punto débil de las IA de texto es…","ops":["Redactar","Resumir","Hacer cálculos largos exactos","Dar ideas"],"correcta":2},{"p":"La mejor división del trabajo es…","ops":["La IA calcula y Excel interpreta","Excel calcula y la IA interpreta","Ninguno calcula","La IA hace todo"],"correcta":1},{"p":"Una tarea importante pero no urgente se…","ops":["Elimina","Agenda","Delega siempre","Ignora"],"correcta":1},{"p":"La técnica del «abogado del diablo» sirve para…","ops":["Encontrar debilidades de tu idea","Escribir más largo","Traducir","Hacer tablas"],"correcta":0},{"p":"¿Quién es responsable de la decisión final?","ops":["La IA","Tú","La empresa que hizo la IA","Nadie"],"correcta":1}]}},{"id":"c-ia-m5","titulo":"Módulo 5 — Más allá del texto y proyecto final","resumen":"Cierras el curso con las funciones de imagen y voz, las reglas éticas para usar IA en el trabajo, una rutina semanal para que no se quede en curiosidad y un proyecto final donde resuelves un caso real de principio a fin. Cuatro lecciones y la evaluación final.","lecciones":[{"id":"c-ia-m5-l1","titulo":"Lección 1 — Imágenes, fotos y voz","objetivo":"usar la IA para leer fotos y documentos, generar imágenes sencillas y trabajar por voz.","bloques":[{"tipo":"texto","texto":"Las herramientas actuales no solo leen y escriben texto: pueden <b>ver</b> fotos, <b>crear</b> imágenes y <b>escuchar y hablar</b>. No necesitas dominar todo, pero conocer estas funciones te abre usos muy prácticos."},{"tipo":"titulo","texto":"Que la IA vea una foto"},{"tipo":"lista","items":["<b>Un ticket o factura:</b> «Pasa este ticket a una tabla con concepto, cantidad y precio.»","<b>Un pizarrón o rotafolio de una junta:</b> «Transcribe lo que dice y ordénalo en acuerdos y pendientes.»","<b>Un error en pantalla:</b> tómale captura y pregunta «¿qué significa este error y cómo lo soluciono?».","<b>Una gráfica:</b> «¿Qué me dice esta gráfica? ¿Qué conclusiones sacarías?»","<b>Un letrero o menú en otro idioma:</b> «Tradúcelo.»"]},{"tipo":"destacado","texto":"<b>Revisa los números leídos de fotos.</b> Si la foto está borrosa o inclinada, la IA puede leer un 8 como 3. Para documentos importantes, compara al menos los totales."},{"tipo":"titulo","texto":"Crear imágenes"},{"tipo":"texto","texto":"Varias herramientas pueden generar imágenes a partir de una descripción: ilustraciones para una presentación, ideas para un logotipo, una imagen para una publicación. Funcionan mejor cuando describes <b>qué</b>, <b>estilo</b>, <b>colores</b> y <b>para qué</b>."},{"tipo":"plantilla","rotulo":"Pedir una imagen","texto":"Crea una imagen de [qué debe aparecer], estilo [ilustración plana / fotografía realista / acuarela], colores [paleta], formato [cuadrado para Instagram / horizontal para presentación]. Sin texto dentro de la imagen.","nota":"«Sin texto dentro de la imagen» evita letreros con faltas de ortografía, un error muy común en imágenes generadas. El texto agrégalo tú después en Canva o PowerPoint."},{"tipo":"comparar","titulo":"Usos adecuados e inadecuados","malTitulo":"Evita","mal":"• Imitar el logo o el personaje de otra marca<br>• Fotos «realistas» de personas reales o de hechos que no pasaron<br>• Hacer pasar una imagen generada como foto real de tu producto","bienTitulo":"Bien","bien":"• Ilustraciones para presentaciones<br>• Bocetos e ideas para un diseñador<br>• Fondos y elementos decorativos<br>• Imágenes para publicaciones, dejando claro que son ilustrativas"},{"tipo":"titulo","texto":"Trabajar con la voz"},{"tipo":"lista","items":["<b>Dictar:</b> el micrófono convierte lo que dices en texto. Ideal para vaciar ideas o pendientes.","<b>Modo conversación:</b> varias apps permiten platicar en voz alta con la IA, como una llamada. Sirve para practicar una presentación o un idioma.","<b>Escuchar respuestas:</b> que te lea la respuesta mientras manejas o caminas."]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Le pasas foto de una factura y te da la tabla. Antes de capturarla en contabilidad…","ops":["La uso directo","Comparo al menos el total contra la factura"],"correcta":1},{"p":"Para que una imagen generada no tenga letras mal escritas, pides…","ops":["«Sin texto dentro de la imagen»","«Con mucho texto»"],"correcta":0},{"p":"¿Cuál es un uso adecuado?","ops":["Crear una ilustración para tu presentación","Crear una «foto» de tu competencia haciendo algo que no hizo"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Tu uso visual","pregunta":"Prueba una de estas funciones con algo real (una foto de un ticket, una captura de pantalla, una imagen para una presentación). Escribe qué hiciste y qué tan útil fue.","ayuda":"Le mandé… Me devolvió…"},{"tipo":"clave","items":["La IA puede leer fotos: tickets, pizarrones, errores, gráficas.","Imágenes: qué, estilo, colores, formato, sin texto.","Voz: dicta, conversa, escucha.","Verifica números y no engañes con imágenes."]}]},{"id":"c-ia-m5-l2","titulo":"Lección 2 — Ética y reglas del juego en el trabajo","objetivo":"usar la IA de forma honesta y responsable: transparencia, derechos de autor, sesgos y políticas de tu empresa.","bloques":[{"tipo":"texto","texto":"Usar IA en el trabajo no es hacer trampa: es usar una herramienta, como la calculadora o el corrector ortográfico. Pero como toda herramienta poderosa, tiene reglas de uso. Conocerlas te protege a ti, a tu empresa y a tus clientes."},{"tipo":"titulo","texto":"Cinco reglas"},{"tipo":"tabla","titulo":"Usar IA con responsabilidad","encabezados":["Regla","Qué significa en la práctica"],"filas":[["<b>1. Tú firmas</b>","Todo lo que envías es tu responsabilidad, lo haya escrito quien lo haya escrito. Revísalo."],["<b>2. Sé transparente cuando importa</b>","Si un cliente, maestro o jefe espera que algo sea 100% tuyo (un examen, una opinión profesional, un trabajo académico), no lo presentes como propio sin decirlo. Sigue las reglas del lugar."],["<b>3. Cuida los datos</b>","Nada de información personal o confidencial en herramientas no autorizadas (módulo 1)."],["<b>4. Respeta a los autores</b>","No le pidas que copie textos, canciones, imágenes o marcas de otros para usarlos como tuyos."],["<b>5. Vigila los sesgos</b>","La IA aprendió de textos humanos y puede repetir prejuicios (de género, edad, origen). Revisa especialmente en temas de personas: vacantes, evaluaciones, descripciones."]]},{"tipo":"titulo","texto":"Los sesgos, con un ejemplo"},{"tipo":"comparar","titulo":"Un anuncio de vacante","malTitulo":"Con sesgo (sin querer)","mal":"«Buscamos joven dinámico, recién egresado, con excelente presentación, para puesto de ingeniero.»<br>Excluye por edad y asume género.","bienTitulo":"Revisado","bien":"«Buscamos ingeniera o ingeniero con conocimientos en [área], capacidad de trabajo en equipo y ganas de aprender. Experiencia deseable, no indispensable.»","nota":"Puedes pedirle a la IA: «Revisa este texto y dime si tiene lenguaje que pueda discriminar por edad, género, origen o apariencia.»"},{"tipo":"destacado","texto":"<b>Pregunta por la política de tu empresa.</b> Muchas empresas ya tienen reglas sobre qué herramientas de IA se pueden usar y con qué información. Si la tuya no la tiene, es buena idea proponerla. Y si estudias, cada escuela tiene sus propias reglas sobre el uso de IA en tareas."},{"tipo":"practica","rotulo":"¿Qué harías?","preguntas":[{"p":"Tu empresa prohíbe subir documentos internos a herramientas de IA públicas. Tienes un contrato que resumir.","ops":["Lo subo igual, nadie se entera","Uso la herramienta autorizada por la empresa o lo resumo sin la IA"],"correcta":1},{"p":"La IA te dio un párrafo que se parece mucho a un artículo de otra empresa.","ops":["Lo publico","Lo reescribo con mis palabras o cito la fuente"],"correcta":1},{"p":"Usaste la IA para redactar un informe que presentas a tu jefe.","ops":["Es válido si lo revisaste, los datos son correctos y respetas las reglas de tu empresa","Está prohibido siempre"],"correcta":0},{"p":"La IA describió a «el gerente» y «la secretaria» en un caso de capacitación.","ops":["Está bien","Lo reviso para no reforzar estereotipos"],"correcta":1}]},{"tipo":"reflexion","rotulo":"Tus reglas","pregunta":"Escribe en 3 frases cómo vas a usar la IA de forma responsable en tu trabajo. Si tu empresa tiene una política, resume aquí lo más importante.","ayuda":"Voy a… Nunca voy a… Siempre voy a…"},{"tipo":"clave","items":["Tú firmas: revisa todo.","Transparencia cuando se espera trabajo 100% tuyo.","Respeta autores y marcas.","Revisa sesgos en temas de personas.","Sigue la política de tu empresa o escuela."]}]},{"id":"c-ia-m5-l3","titulo":"Lección 3 — Tu rutina semanal con IA","objetivo":"integrar la IA a tu semana con una rutina concreta para que se vuelva hábito y no curiosidad.","bloques":[{"tipo":"texto","texto":"La mayoría de la gente prueba la IA, se emociona una semana y la olvida. La diferencia la hace tener <b>momentos fijos</b> en tu semana donde la usas siempre. Aquí armas tu rutina."},{"tipo":"tabla","titulo":"Una rutina de ejemplo","encabezados":["Momento","Uso","Tiempo que ahorra"],"filas":[["Lunes, 15 min","Vaciar pendientes y priorizar la semana (M4 L4)","30–60 min de indecisión"],["Cada día","Correos difíciles y mensajes a clientes (M3)","10–20 min diarios"],["Después de cada junta","Notas → minuta con pendientes (M3 L3)","20 min por junta"],["Cuando llega información desordenada","Pasarla a tabla (M4 L1)","30 min o más"],["Viernes, 10 min","Resumen de lo logrado para tu jefe o para ti","15 min"]]},{"tipo":"plantilla","rotulo":"Resumen semanal para tu jefe","texto":"Estas son mis notas de lo que hice esta semana: [pega o dicta]. Conviértelas en un resumen de máximo 150 palabras para mi jefe, con: 3 logros principales, pendientes para la próxima semana y cualquier obstáculo en el que necesite apoyo. Tono profesional y breve."},{"tipo":"titulo","texto":"Mide tu ahorro"},{"tipo":"texto","texto":"Durante dos semanas, cada vez que uses la IA en una tarea, anota cuánto tiempo te habría tomado sin ella y cuánto te tomó con ella. Te va a sorprender, y es un argumento excelente si quieres proponer su uso en tu área o pedir una herramienta con licencia empresarial."},{"tipo":"pasos","rotulo":"Arma tu rutina","pasos":["Elige 3 momentos de tu semana en los que vas a usar la IA sí o sí.","Pon un recordatorio en tu calendario para el primero (por ejemplo, lunes 9:00 — «Priorizar semana con IA»).","Ten a la mano tu biblioteca de instrucciones (M2 L5).","Anota el tiempo ahorrado durante 2 semanas.","Al final de las 2 semanas, ajusta: quita lo que no sirvió, agrega lo que descubriste."]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Qué hace que la IA se vuelva hábito?","ops":["Usarla cuando me acuerde","Tener momentos fijos en la semana"],"correcta":1},{"p":"¿Para qué medir el tiempo ahorrado?","ops":["Para saber qué usos valen la pena y poder justificarlo","No sirve"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Tu rutina","pregunta":"Escribe tus 3 momentos fijos de la semana para usar IA, con día, hora y tarea.","ayuda":"1. Lunes 9:00 — … 2. … 3. …"},{"tipo":"clave","items":["Momentos fijos → hábito.","Empieza con 3 usos, no con 20.","Mide el tiempo ahorrado dos semanas."]}]},{"id":"c-ia-m5-l4","titulo":"Lección 4 — Proyecto final: resuelve un caso de principio a fin","objetivo":"aplicar todo el curso en un caso completo: entender, investigar, organizar, redactar y verificar.","bloques":[{"tipo":"texto","texto":"Es momento de juntar todo. Vas a resolver un caso realista usando la IA en cada paso, como lo harías en tu trabajo. Puedes usar el caso de ejemplo o, mejor aún, <b>un problema real tuyo</b>."},{"tipo":"destacado","texto":"<b>El caso:</b> trabajas en una pequeña empresa de mantenimiento de aires acondicionados en Monterrey. En los últimos 3 meses las quejas de clientes subieron: técnicos que llegan tarde, citas que no se confirman y clientes que no reciben su factura. Tu jefe te pide: 1) entender qué pasa, 2) proponer soluciones, 3) escribir un mensaje para los clientes afectados y 4) presentar un plan de 30 días."},{"tipo":"titulo","texto":"Paso 1 — Entender (M4)"},{"tipo":"plantilla","rotulo":"Ordenar las quejas","texto":"Estas son las quejas de clientes de los últimos 3 meses (sin datos personales):\n[pegar quejas]\n\nOrganízalas en una tabla: fecha, tipo de problema (retraso, confirmación, facturación, otro), descripción breve. Luego dime cuántas hay de cada tipo y qué patrones ves. No inventes quejas que no estén en la lista."},{"tipo":"titulo","texto":"Paso 2 — Pensar soluciones (M4 L5)"},{"tipo":"plantilla","rotulo":"Soluciones con criterio","texto":"Somos una empresa de 8 técnicos y 2 personas en oficina, con presupuesto limitado. Los problemas principales son: [resultado del paso 1]. Dame 10 posibles soluciones, de las más sencillas y baratas a las más ambiciosas, en una tabla con costo, dificultad y tiempo para ver resultados. Luego actúa como abogado del diablo con las 3 mejores."},{"tipo":"titulo","texto":"Paso 3 — Comunicar (M3)"},{"tipo":"plantilla","rotulo":"Mensaje a clientes afectados","texto":"Escribe un mensaje de WhatsApp para clientes que tuvieron retrasos o problemas con su factura. Reconoce el problema sin excusas, explica en una frase qué estamos cambiando ([solución]) y ofrece [compensación, si hay]. Máximo 5 renglones, tono cálido y profesional, español de México."},{"tipo":"titulo","texto":"Paso 4 — Planear (M4 L4)"},{"tipo":"plantilla","rotulo":"Plan de 30 días","texto":"Con base en estas soluciones elegidas: [soluciones], arma un plan de 30 días en una tabla con: semana, acción, responsable (técnicos / oficina / jefe), indicador para medir si funcionó. Al final, un resumen ejecutivo de 5 renglones para mi jefe."},{"tipo":"titulo","texto":"Paso 5 — Verificar (M1)"},{"tipo":"pasos","rotulo":"Lista de verificación final","pasos":["Los números del paso 1 (cuántas quejas de cada tipo) coinciden con la lista original.","Las soluciones son realistas para el tamaño y presupuesto de la empresa.","El mensaje a clientes no promete nada que no se pueda cumplir.","No hay datos personales de clientes en lo que compartiste con la IA.","El plan tiene responsables y fechas claras.","Leíste todo completo y lo ajustaste con tu criterio."]},{"tipo":"reflexion","rotulo":"Tu entrega","pregunta":"Escribe aquí tu resumen ejecutivo final (o el de tu propio caso real): el problema, las 3 soluciones elegidas y el mensaje a clientes.","ayuda":"Problema: … Soluciones: … Mensaje: …"},{"tipo":"practica","rotulo":"Repaso del curso","preguntas":[{"p":"¿En qué paso es más importante verificar números?","ops":["Al ordenar y contar las quejas","Al pedir ideas"],"correcta":0},{"p":"¿Qué haces con los nombres y teléfonos de los clientes que se quejaron?","ops":["Los pego para que la IA personalice","Los quito antes de compartir"],"correcta":1},{"p":"La IA propone contratar 5 técnicos más. Para una empresa de 8…","ops":["Lo acepto","Lo evalúo con criterio: quizá no es realista y pido alternativas baratas"],"correcta":1}]},{"tipo":"destacado","texto":"<b>¡Terminaste el curso!</b> Ya sabes qué es la IA y qué no, cómo pedirle las cosas, cómo usarla para escribir, ordenar datos, planear y decidir, y cómo hacerlo con responsabilidad. El siguiente paso natural es un curso de <b>IA aplicada a tu profesión</b>, donde verás casos específicos de tu área."},{"tipo":"clave","titulo":"Lo que ya sabes hacer","items":["Entender cómo funciona la IA y cuándo verificar.","Escribir instrucciones completas y pulir en vueltas.","Redactar correos, mensajes, minutas y resúmenes.","Ordenar datos, pedir fórmulas e interpretar números.","Planear, decidir y usar la IA con ética."]}]}],"quiz":{"titulo":"Evaluación final del curso","preguntas":[{"p":"Le pasas a la IA la foto de un ticket. Antes de usar los datos…","ops":["Comparas al menos el total","Los usas directo","Borras la foto","Le pides otra foto"],"correcta":0},{"p":"Para evitar letras mal escritas en una imagen generada, pides…","ops":["«Sin texto dentro de la imagen»","«Con letras grandes»","«En inglés»","Nada"],"correcta":0},{"p":"¿Quién es responsable de lo que envías aunque lo haya escrito la IA?","ops":["La IA","Tú","Nadie","La empresa de IA"],"correcta":1},{"p":"Un sesgo en la IA es…","ops":["Un prejuicio aprendido de textos humanos","Un error de internet","Un tipo de archivo","Un virus"],"correcta":0},{"p":"Tu empresa prohíbe subir documentos internos a IA públicas. Tú…","ops":["Usas la herramienta autorizada o no usas IA para eso","Lo subes igual","Le cambias el nombre al archivo","Lo subes desde tu celular"],"correcta":0},{"p":"Lo que más ayuda a volver la IA un hábito es…","ops":["Tener momentos fijos en la semana","Usarla solo en emergencias","Probar 20 herramientas","Leer noticias de IA"],"correcta":0},{"p":"Para cálculos exactos con muchos números usas…","ops":["Excel","La memoria","La IA sin revisar","Una imagen"],"correcta":0},{"p":"La instrucción de 4 partes incluye…","ops":["Papel, tarea, contexto y formato","Nombre, fecha, firma y sello","Título, imagen, color y fuente","Saludo, pregunta, gracias y adiós"],"correcta":0},{"p":"Para anonimizar un caso con clientes…","ops":["Cambias nombres y quitas datos de contacto","Pegas todo","Usas iniciales y teléfono","Pides permiso a la IA"],"correcta":0},{"p":"Cuando la IA propone una solución poco realista para tu empresa…","ops":["La aceptas","La evalúas con tu criterio y pides alternativas","Cierras la herramienta","La mandas a tu jefe sin revisar"],"correcta":1},{"p":"Una minuta confiable marca lo dudoso como…","ops":["[por confirmar]","Correcto","Urgente","Nada"],"correcta":0},{"p":"La mejor forma de lograr un estilo específico es…","ops":["Mostrar ejemplos","Describirlo con adjetivos","Pedir que sea creativo","Usar mayúsculas"],"correcta":0}]}}]});
